      h1: any;
      h2: any;
      h3: any;
      h4: any;
      h5: any;
      h6: any;
      p: any;
      br: any;
      hr: any;
      button: any;
      input: any;
      label: any;
      select: any;
      option: any;
      textarea: any;
      header: any;
      footer: any;
      section: any;
      nav: any;
      canvas: any;
      img: any;
      video: any;
      audio: any;
      a: any;
      ul: any;
      li: any;
      ol: any;
      form: any;
