                        <FileJson className="text-purple-400" /> 
                        Saved Projects
                    </h2>
                    <span className="text-xs font-mono text-gray-500 bg-neutral-900 px-2 py-1 rounded">{workspaceName}</span>
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2 pr-2">
                    {isLoading ? (
                        <div className="text-center text-gray-500 py-10">Loading...</div>
                    ) : projects.length === 0 ? (
                        <div className="text-center text-gray-500 py-10 border-2 border-dashed border-white/5 rounded-xl">
                            <Monitor className="mx-auto mb-2 opacity-20" size={32} />
                            <p>No projects found in /projects</p>
                        </div>
                    ) : (
                        projects.map((proj) => (
                            <button 
                                key={proj}
                                onClick={() => onLoadProject(proj)}
                                className="w-full text-left p-4 rounded-xl bg-neutral-900 border border-white/5 hover:border-purple-500/50 hover:bg-neutral-800 transition-all group"
                            >
                                <span className="font-bold text-gray-300 group-hover:text-white block mb-1">
                                    {proj.replace('.json', '')}
                                </span>
                                <span className="text-[10px] text-gray-600 bg-black/30 px-1.5 py-0.5 rounded border border-white/5">
                                    Video Lyrics
                                </span>
                            </button>
                        ))
                    )}
                </div>
            </div>
        </div>
      )}

      <div className="mt-8 text-xs text-gray-600">
         v1.3.0 &bull; File System Access Enabled
      </div>
    </div>
  );
};

