// Helper: Convert Blob to Base64
const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      resolve(result);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

// Helper: Convert Base64 to Blob
const base64ToBlob = async (base64: string): Promise<Blob> => {
  const res = await fetch(base64);
  return res.blob();
};

const parseSrtTimestamp = (timestamp: string): number => {
  if (!timestamp) return 0;
  const normalized = timestamp.replace(',', '.').trim();
  const parts = normalized.split(':');
  if (parts.length < 3) return 0; 
  const hours = parseFloat(parts[0]);
  const minutes = parseFloat(parts[1]);
  const seconds = parseFloat(parts[2]);
  return (hours * 3600) + (minutes * 60) + seconds;
};

const parseSrtToLyricData = (srtContent: string): LyricData => {
  const normalizedContent = srtContent.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const blocks = normalizedContent.trim().split(/\n\s*\n/);
  const segments: Segment[] = [];

  blocks.forEach((block, index) => {
    const lines = block.split('\n');
    if (lines.length < 2) return;
    let timeLineIndex = lines.findIndex(l => l.includes('-->'));
    if (timeLineIndex === -1) return;
    const timeLine = lines[timeLineIndex];
    const [startStr, endStr] = timeLine.split('-->');
    if (!startStr || !endStr) return;
    const start = parseSrtTimestamp(startStr);
    const end = parseSrtTimestamp(endStr);
    const textLines = lines.slice(timeLineIndex + 1).map(l => l.replace(/<[^>]*>/g, '').trim()).filter(l => l.length > 0);
    const fullText = textLines.join(' ');
    if (!fullText) return;
    const words: Word[] = [];
    const totalDuration = end - start;
    let allWords: {text: string, line: number}[] = [];
    textLines.forEach((line, lineIdx) => {
        const lineWords = line.split(/\s+/);
        lineWords.forEach(w => allWords.push({ text: w, line: lineIdx }));
    });
    const wordDuration = totalDuration / allWords.length;
    allWords.forEach((wObj, i) => {
      words.push({ word: wObj.text, start: start + (i * wordDuration), end: start + ((i + 1) * wordDuration), probability: 1.0, line_number: wObj.line });
    });
    segments.push({ id: index.toString(), start, end, text: fullText, section: 'verse', words });
  });
  return { segments };
};

const extractAudioAnalysis = (audioBuffer: AudioBuffer, fps: number, duration: number): AudioVisualizerData[] => {
    if (!duration || duration <= 0 || !Number.isFinite(duration)) return [];
    const totalFrames = Math.ceil(duration * fps);
    const result: AudioVisualizerData[] = new Array(totalFrames);
    const rawData = audioBuffer.getChannelData(0); 
    const sampleRate = audioBuffer.sampleRate;
    const samplesPerFrame = Math.floor(sampleRate / fps);
    const fftSize = 256;
    const frequencyBinCount = fftSize / 2;
    for (let i = 0; i < totalFrames; i++) {
        const startSample = i * samplesPerFrame;
        const endSample = Math.min(startSample + samplesPerFrame, rawData.length);
        let sum = 0; let diffSum = 0; let highFreqSum = 0;
        for (let j = startSample; j < endSample; j++) {
            const val = rawData[j]; sum += val * val; 
            if (j > startSample) { const diff = val - rawData[j-1]; diffSum += diff * diff; 
                if (j > startSample + 1) { const diff2 = (val - rawData[j-1]) - (rawData[j-1] - rawData[j-2]); highFreqSum += diff2 * diff2; } }
        }
        const rms = Math.sqrt(sum / (endSample - startSample)) || 0;
        const diffRms = Math.sqrt(diffSum / (endSample - startSample)) || 0;
        const highRms = Math.sqrt(highFreqSum / (endSample - startSample)) || 0;
        const bass = Math.min(1, rms * 4); const mid = Math.min(1, diffRms * 8); const high = Math.min(1, highRms * 16);
        const dataArray = new Uint8Array(frequencyBinCount);
        const bassBins = 10; const midBins = 90;
        for(let k=0; k<frequencyBinCount; k++) {
            if (k < bassBins) dataArray[k] = bass * 255;
            else if (k < bassBins + midBins) dataArray[k] = mid * 255;
            else dataArray[k] = high * 255;
        }
        result[i] = { bass, mid, high, raw: dataArray };
    }
    return result;
};

export default function App() {
  // --- APP STATE ---
  const [viewMode, setViewMode] = useState<'launcher' | 'editor'>('launcher');

  // File System State
  const [rootHandle, setRootHandle] = useState<FileSystemDirectoryHandle | null>(null);
  const [projectsList, setProjectsList] = useState<string[]>([]);
  const [fsLoading, setFsLoading] = useState(false);
  const [currentProjectName, setCurrentProjectName] = useState<string>('Untitled');

  // Editor State
  const [data, setData] = useState<LyricData>(DEFAULT_LYRICS);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [eventBlocks, setEventBlocks] = useState<EventBlock[]>([]);
  const [audioLayers, setAudioLayers] = useState<AudioLayer[]>([]);
  const [customEffects, setCustomEffects] = useState<CustomEffect[]>([]);
  const backgroundFileRef = useRef<{ file: Blob, type: 'image' | 'video' } | null>(null);
  const fontFilesRef = useRef<Map<string, Blob>>(new Map());
  const [renderStatus, setRenderStatus] = useState<RenderStatus>({ state: 'idle', progress: 0 });
  const [audioVisualizerData, setAudioVisualizerData] = useState<AudioVisualizerData>({ bass: 0, mid: 0, high: 0, raw: new Uint8Array() });
  const [rendererConfig, setRendererConfig] = useState<RendererConfig>(TEMPLATES[0]);
  const [exportFormat, setExportFormat] = useState<'webm' | 'mp4'>('mp4');
  const [exportMode, setExportMode] = useState<'normal' | 'alpha'>('normal');
  const [cachedBlob, setCachedBlob] = useState<Blob | null>(null);
  const [isCaching, setIsCaching] = useState(false);

  // Refs
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const audioDestinationRef = useRef<MediaStreamAudioDestinationNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourcesRef = useRef<Map<string, AudioBufferSourceNode>>(new Map());
  const gainsRef = useRef<Map<string, GainNode>>(new Map());
  const rendererRef = useRef<CanvasVideoRendererRef>(null);
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // --- FILE SYSTEM HELPERS ---

  const initWorkspace = async () => {
      try {
          const handle = await window.showDirectoryPicker({ id: 'appmigna', mode: 'readwrite' });
          if (!handle) return;
          setRootHandle(handle);
          setFsLoading(true);

          // Ensure Scaffolding
          await handle.getDirectoryHandle('projects', { create: true });
          await handle.getDirectoryHandle('final_renders', { create: true });
          const shadersHandle = await handle.getDirectoryHandle('shaders', { create: true });

          // Load Projects List
          await refreshProjectsList(handle);

          // Load Global Shaders
          await loadShadersFromDisk(shadersHandle);

          setFsLoading(false);
      } catch (e) {
          console.error("Workspace Init Failed", e);
          setFsLoading(false);
          alert("Could not access folder. Please try again.");
      }
  };

  const refreshProjectsList = async (root: FileSystemDirectoryHandle) => {
      const projectsDir = await root.getDirectoryHandle('projects');
      const list: string[] = [];
      // @ts-ignore
      for await (const entry of projectsDir.values()) {
          if (entry.kind === 'file' && entry.name.endsWith('.json')) {
              list.push(entry.name);
          }
      }
      setProjectsList(list);
  };

  const loadShadersFromDisk = async (shadersDir: FileSystemDirectoryHandle) => {
      const loaded: CustomEffect[] = [];
      // @ts-ignore
      for await (const entry of shadersDir.values()) {
          if (entry.kind === 'file' && entry.name.endsWith('.json')) {
              const fileHandle = entry as FileSystemFileHandle;
              const file = await fileHandle.getFile();
              const text = await file.text();
              try {
                  const fx = JSON.parse(text);
                  loaded.push(fx);
              } catch(e) {}
          }
      }
      if (loaded.length > 0) setCustomEffects(loaded);
  };

  const saveShadersToDisk = async (newEffects: CustomEffect[]) => {
      if (!rootHandle) return;
      try {
          const shadersDir = await rootHandle.getDirectoryHandle('shaders');
          // Simple sync: write all. Optimally we check diffs, but this is fine for now.
          for (const fx of newEffects) {
              const fileHandle = await shadersDir.getFileHandle(`${fx.id}.json`, { create: true });
              const writable = await fileHandle.createWritable();
              await writable.write(JSON.stringify(fx, null, 2));
              await writable.close();
          }
      } catch(e) { console.error("Shader save error", e); }
  };

  const handleCustomEffectsUpdate = (fx: CustomEffect[]) => {
      setCustomEffects(fx);
      saveShadersToDisk(fx);
  };

  // --- LAUNCHER ACTIONS ---

  const handleCreateProject = (type: AppProjectType, name: string) => {
      // Reset State
      setData(DEFAULT_LYRICS);
      setRendererConfig(TEMPLATES[0]);
      setAudioLayers([]);
      setEventBlocks([]);
      setCachedBlob(null);
      backgroundFileRef.current = null;
      fontFilesRef.current.clear();
      setCurrentProjectName(name);
      setViewMode('editor');
  };

  const handleLoadProjectFromDisk = async (filename: string) => {
      if (!rootHandle) return;
      setFsLoading(true);
      try {
          const projectsDir = await rootHandle.getDirectoryHandle('projects');
          const fileHandle = await projectsDir.getFileHandle(filename);
          const file = await fileHandle.getFile();
          const text = await file.text();
          const project = JSON.parse(text) as ProjectFile;

          // Restore State
          setCurrentProjectName(project.name);
          if (project.lyricData) setData(project.lyricData);
          if (project.config) setRendererConfig(project.config);
          if (project.eventBlocks) setEventBlocks(project.eventBlocks);

          // Merge custom effects (prioritize disk global or project local? let's merge unique IDs)
          if (project.customEffects) {
              setCustomEffects(prev => {
                  const combined = [...prev];
                  project.customEffects?.forEach(pFx => {
                      if (!combined.find(c => c.id === pFx.id)) combined.push(pFx);
                  });
                  return combined;
              });
          }

          // Restore Assets
          if (project.assets) {
              initAudioEngine();
              const restoredLayers: AudioLayer[] = [];
              for (const audioAsset of project.assets.audio) {
                  const blob = await base64ToBlob(audioAsset.data);
                  const arrayBuffer = await blob.arrayBuffer();
                  const audioBuffer = await audioContextRef.current!.decodeAudioData(arrayBuffer);
                  restoredLayers.push({
                      id: audioAsset.id, name: audioAsset.name, buffer: audioBuffer,
                      volume: audioAsset.volume, muted: audioAsset.muted, solo: audioAsset.solo,
                      duration: audioBuffer.duration, sourceFile: blob, mimeType: audioAsset.mimeType
                  });
              }
              setAudioLayers(restoredLayers);
              if (restoredLayers.length > 0) setDuration(Math.max(...restoredLayers.map(l => l.duration)));

              if (project.assets.background) {
                  const blob = await base64ToBlob(project.assets.background.data);
                  const url = URL.createObjectURL(blob);
                  backgroundFileRef.current = { file: blob, type: project.assets.background.type };
                  setRendererConfig(prev => ({ ...prev, background: { ...prev.background, type: project.assets.background!.type, url: url } }));
              }

              for (const fontAsset of project.assets.fonts) {
                  const blob = await base64ToBlob(fontAsset.data);
                  fontFilesRef.current.set(fontAsset.name, blob);
                  const url = URL.createObjectURL(blob);
                  const fontFace = new FontFace(fontAsset.name, `url(${url})`);
                  try { const loaded = await fontFace.load(); document.fonts.add(loaded); } catch(e) {}
              }
          }
          setViewMode('editor');
      } catch (e) {
          console.error(e);
          alert("Failed to load project file");
      } finally {
          setFsLoading(false);
      }
  };


  // --- APP LOGIC (Mixer, Playback, Render) ---
  const initAudioEngine = () => {
      if (!audioContextRef.current) {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          const ctx = new AudioContext();
          audioContextRef.current = ctx;
          const masterGain = ctx.createGain();
          masterGain.connect(ctx.destination);
          masterGainRef.current = masterGain;
          const dest = ctx.createMediaStreamDestination();
          masterGain.connect(dest);
          audioDestinationRef.current = dest;
          const analyser = ctx.createAnalyser();
          analyser.fftSize = 256;
          masterGain.connect(analyser); 
          analyserRef.current = analyser;
      } else if (audioContextRef.current.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  useEffect(() => { if (cachedBlob) setCachedBlob(null); }, [data, rendererConfig, audioLayers, eventBlocks, customEffects]);

  const handleAudioLayerAdd = async (file: File) => {
      initAudioEngine();
      if (!audioContextRef.current) return;
      try {
          const arrayBuffer = await file.arrayBuffer();
          const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);
          const newLayer: AudioLayer = {
              id: Date.now().toString() + Math.random().toString(),
              name: file.name, buffer: audioBuffer, volume: 1.0, muted: false, solo: false,
              duration: audioBuffer.duration, sourceFile: file, mimeType: file.type
          };
          setAudioLayers(prev => {
              const updated = [...prev, newLayer];
              setDuration(Math.max(...updated.map(l => l.duration)));
              return updated;
          });
      } catch (e) { console.error(e); alert("Failed to load audio"); }
  };

  const updateLayer = (id: string, updates: Partial<AudioLayer>) => {
      setAudioLayers(prev => prev.map(l => l.id === id ? { ...l, ...updates } : l));
  };
  const removeLayer = (id: string) => {
      setAudioLayers(prev => {
          const updated = prev.filter(l => l.id !== id);
          const maxDur = Math.max(...updated.map(l => l.duration), 0);
          setDuration(maxDur);
          return updated;
      });
  };

  const handleAssetLoaded = (type: 'background' | 'font', file: File, meta?: string) => {
      if (type === 'background') backgroundFileRef.current = { file, type: file.type.startsWith('video') ? 'video' : 'image' };
      else if (type === 'font' && meta) fontFilesRef.current.set(meta, file);
  };

  useEffect(() => {
     if (!audioContextRef.current) return;
     const hasSolo = audioLayers.some(l => l.solo);
     audioLayers.forEach(layer => {
         if (!gainsRef.current.has(layer.id)) {
             const g = audioContextRef.current!.createGain();
             if (masterGainRef.current) g.connect(masterGainRef.current);
             gainsRef.current.set(layer.id, g);
         }
         const gainNode = gainsRef.current.get(layer.id);
         if (gainNode) {
             const effectiveMute = layer.muted || (hasSolo && !layer.solo);
             gainNode.gain.setTargetAtTime(effectiveMute ? 0 : layer.volume, audioContextRef.current!.currentTime, 0.05);
         }
     });
     gainsRef.current.forEach((val, key) => { if (!audioLayers.find(l => l.id === key)) { val.disconnect(); gainsRef.current.delete(key); } });
  }, [audioLayers]);

  const stopAllSources = () => { sourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} s.disconnect(); }); sourcesRef.current.clear(); };
  const startAllSources = (offset: number) => {
      if (!audioContextRef.current) return;
      stopAllSources();
      audioLayers.forEach(layer => {
          const source = audioContextRef.current!.createBufferSource();
          source.buffer = layer.buffer;
          const gain = gainsRef.current.get(layer.id);
          if (gain) source.connect(gain);
          source.start(0, offset);
          sourcesRef.current.set(layer.id, source);
      });
  };

  const startRecordingCache = () => {
      if (!rendererRef.current?.canvas || !audioDestinationRef.current) return;
      try {
          const combined = new MediaStream([...rendererRef.current.canvas.captureStream(60).getVideoTracks(), ...audioDestinationRef.current.stream.getAudioTracks()]);
          const recorder = new MediaRecorder(combined, { mimeType: 'video/webm;codecs=vp9', videoBitsPerSecond: 8000000 });
          recordedChunksRef.current = [];
          recorder.ondataavailable = (e) => { if (e.data.size > 0) recordedChunksRef.current.push(e.data); };
          recorder.start();
          mediaRecorderRef.current = recorder;
          setIsCaching(true);
      } catch (err) {}
  };

  const stopRecordingCache = (save: boolean) => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();
          if (save && recordedChunksRef.current.length > 0) setCachedBlob(new Blob(recordedChunksRef.current, { type: 'video/webm' }));
      }
      setIsCaching(false); mediaRecorderRef.current = null;
  };

  const togglePlay = () => {
    initAudioEngine();
    if (!audioContextRef.current) return;
    if (isPlaying) {
      if (isCaching) stopRecordingCache(false);
      audioContextRef.current.suspend();
      setIsPlaying(false);
    } else {
      audioContextRef.current.resume();
      if (sourcesRef.current.size === 0) {
          if (currentTime < 0.1) { setCachedBlob(null); startRecordingCache(); }
          startAllSources(currentTime);
          startTimeRef.current = audioContextRef.current.currentTime - currentTime;
      }
      setIsPlaying(true);
    }
  };

  const handleSeek = (time: number) => {
      if (!audioContextRef.current) return;
      if (isCaching) stopRecordingCache(false);
      const wasPlaying = isPlaying;
      audioContextRef.current.suspend();
      stopAllSources();
      setCurrentTime(time);
      startTimeRef.current = audioContextRef.current.currentTime - time;
      if (wasPlaying) { startAllSources(time); audioContextRef.current.resume(); }
  };

  const analyzeAudio = () => {
    if (analyserRef.current) {
      const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
      analyserRef.current.getByteFrequencyData(dataArray);
      const avg = (arr: Uint8Array) => arr.reduce((a, b) => a + b, 0) / arr.length;
      setAudioVisualizerData({ bass: avg(dataArray.slice(0, 10)) / 255, mid: avg(dataArray.slice(10, 100)) / 255, high: avg(dataArray.slice(100, 200)) / 255, raw: dataArray });
    }
  };

  const loop = () => {
    if (isPlaying && audioContextRef.current) {
        let syncedTime = audioContextRef.current.currentTime - startTimeRef.current;
        if (syncedTime >= duration && duration > 0) { syncedTime = duration; if (isCaching) stopRecordingCache(true); setIsPlaying(false); stopAllSources(); audioContextRef.current.suspend(); }
        setCurrentTime(syncedTime); analyzeAudio();
    }
    if (rendererRef.current) rendererRef.current.drawFrame(currentTime, audioVisualizerData, false);
    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => { requestRef.current = requestAnimationFrame(loop); return () => cancelAnimationFrame(requestRef.current); }, [currentTime, audioVisualizerData, isPlaying, duration, isCaching]);

  const handleSaveProject = async () => {
      setRenderStatus({ state: 'saving', progress: 0 });
      try {
          const audioAssets = await Promise.all(audioLayers.map(async (layer) => {
              if (layer.sourceFile) return { id: layer.id, name: layer.name, mimeType: layer.mimeType || 'audio/mp3', data: await blobToBase64(layer.sourceFile), volume: layer.volume, muted: layer.muted, solo: layer.solo };
              return null;
          }));
          let backgroundAsset = undefined;
          if (rendererConfig.background.type !== 'procedural' && rendererConfig.background.type !== 'solid' && backgroundFileRef.current) {
              backgroundAsset = { type: backgroundFileRef.current.type, mimeType: backgroundFileRef.current.file.type, data: await blobToBase64(backgroundFileRef.current.file) };
          }
          const fontAssets = await Promise.all(Array.from(fontFilesRef.current.entries()).map(async ([name, blob]) => ({ name, mimeType: blob.type, data: await blobToBase64(blob) })));

          const project: ProjectFile = {
              version: '1.3',
              type: 'video-lyrics',
              timestamp: Date.now(),
              name: currentProjectName,
              lyricData: data,
              config: rendererConfig,
              eventBlocks: eventBlocks,
              assets: { audio: audioAssets.filter(a => a !== null) as any, background: backgroundAsset, fonts: fontAssets },
              customEffects: customEffects
          };

          const jsonString = JSON.stringify(project);

          if (rootHandle) {
              // Save to AppMigna/projects
              const projectsDir = await rootHandle.getDirectoryHandle('projects');
              const fileName = `${currentProjectName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.json`;
              const fileHandle = await projectsDir.getFileHandle(fileName, { create: true });
              const writable = await fileHandle.createWritable();
              await writable.write(jsonString);
              await writable.close();
              alert("Project saved to workspace!");
              refreshProjectsList(rootHandle);
          } else {
              // Fallback Download
              const blob = new Blob([jsonString], { type: 'application/json' });
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `${currentProjectName}.json`;
              a.click();
              URL.revokeObjectURL(url);
          }
      } catch (e) { console.error("Save Error:", e); alert("Failed to save project."); } 
      finally { setRenderStatus({ state: 'idle', progress: 0 }); }
  };

  const startRendering = async () => {
    if (audioLayers.length === 0) return alert("No audio layers.");
    if (renderStatus.state !== 'idle') return;
    const resConfig = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];
    setRenderStatus({ state: 'analyzing', progress: 0 });
    if (isPlaying && audioContextRef.current) { audioContextRef.current.suspend(); setIsPlaying(false); }

    try {
      const sampleRate = 44100; const FPS = 30; const totalFrames = Math.ceil(duration * FPS);
      const offlineCtx = new OfflineAudioContext(2, Math.ceil(Math.max(0.1, duration) * sampleRate), sampleRate);
      const offlineMaster = offlineCtx.createGain(); offlineMaster.connect(offlineCtx.destination);
      audioLayers.forEach(l => { if (l.muted || (audioLayers.some(al=>al.solo) && !l.solo)) return; const s = offlineCtx.createBufferSource(); s.buffer = l.buffer; const g = offlineCtx.createGain(); g.gain.value = l.volume; s.connect(g); g.connect(offlineMaster); s.start(0); });
      const renderedBuffer = await offlineCtx.startRendering();
      const analysisFrames = extractAudioAnalysis(renderedBuffer, FPS, duration);
      setRenderStatus({ state: 'rendering', progress: 0, totalFrames });
      const format = exportMode === 'alpha' ? 'webm' : exportFormat;
      let muxer = format === 'mp4' ? new Mp4Muxer({ target: new Mp4ArrayBufferTarget(), video: { codec: 'avc', width: resConfig.width, height: resConfig.height }, audio: { codec: 'aac', numberOfChannels: 2, sampleRate } }) : new WebMMuxer({ target: new WebMArrayBufferTarget(), video: { codec: 'V_VP9', width: resConfig.width, height: resConfig.height, frameRate: FPS, alpha: exportMode === 'alpha' }, audio: { codec: 'A_OPUS', numberOfChannels: 2, sampleRate } });
      const vEnc = new VideoEncoder({ output: (c, m) => muxer.addVideoChunk(c, m), error: (e) => console.error(e) });
      await vEnc.configure({ codec: format === 'mp4' ? 'avc1.4d002a' : 'vp09.00.10.08', width: resConfig.width, height: resConfig.height, bitrate: 1e7, alpha: exportMode === 'alpha' ? 'keep' : 'discard' });
      const canvas = rendererRef.current?.canvas;
      if (!canvas) throw new Error("No Canvas");
      for (let i = 0; i < totalFrames; i++) {
         const t = i / FPS;
         if (rendererRef.current?.seekToTime) await rendererRef.current.seekToTime(t);
         rendererRef.current?.drawFrame(t, analysisFrames[i] || {bass:0,mid:0,high:0,raw:new Uint8Array(128)}, exportMode === 'alpha');
         const frame = new VideoFrame(canvas, { timestamp: t * 1e6, alpha: exportMode === 'alpha' ? 'keep' : 'discard' });
         if (vEnc.encodeQueueSize > 5) await vEnc.flush();
         vEnc.encode(frame, { keyFrame: i % (FPS * 2) === 0 });
         frame.close();
         if (i % 10 === 0) { setRenderStatus(prev => ({ ...prev, progress: i })); await new Promise(r => setTimeout(r, 0)); }
      }
      setRenderStatus({ state: 'encoding', progress: 100 });
      await vEnc.flush(); vEnc.close();
      const aEnc = new AudioEncoder({ output: (c, m) => muxer.addAudioChunk(c, m), error: console.error });
      aEnc.configure({ codec: format === 'mp4' ? 'mp4a.40.2' : 'opus', numberOfChannels: 2, sampleRate });
      const c0 = renderedBuffer.getChannelData(0); const c1 = renderedBuffer.numberOfChannels > 1 ? renderedBuffer.getChannelData(1) : c0;
      for (let i = 0; i < renderedBuffer.length; i += 4096) {
          const len = Math.min(4096, renderedBuffer.length - i);
          const d = new Float32Array(len * 2);
          for (let j = 0; j < len; j++) { d[j*2] = c0[i+j]; d[j*2+1] = c1[i+j]; }
          const ad = new AudioData({ format: 'f32', sampleRate, numberOfFrames: len, numberOfChannels: 2, timestamp: i / sampleRate * 1e6, data: d });
          aEnc.encode(ad); ad.close();
      }
      await aEnc.flush(); aEnc.close();
      muxer.finalize();
      const blob = new Blob([muxer.target.buffer], { type: format === 'mp4' ? 'video/mp4' : 'video/webm' });

      // Save Logic
      if (rootHandle) {
          const fileName = `${currentProjectName}_render.${format}`;
          const finalDir = await rootHandle.getDirectoryHandle('final_renders');
          const fileHandle = await finalDir.getFileHandle(fileName, { create: true });
          const writable = await fileHandle.createWritable();
          await writable.write(blob);
          await writable.close();
          alert(`Render saved to AppMigna/final_renders/${fileName}`);
      } else {
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a'); a.href = url; a.download = `render.${format}`; a.click();
      }
      setRenderStatus({ state: 'done', progress: 100 });
      setTimeout(() => setRenderStatus({ state: 'idle', progress: 0 }), 3000);
    } catch (e) { console.error(e); setRenderStatus({ state: 'idle', progress: 0 }); alert("Render Failed"); }
  };

  const viewportResolution = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];

  // --- RENDER ---

  if (viewMode === 'launcher') {
      return (
          <ProjectLauncher 
             onSelectWorkspace={initWorkspace}
             workspaceName={rootHandle ? rootHandle.name : null}
             projects={projectsList}
             onLoadProject={handleLoadProjectFromDisk}
             onCreateProject={handleCreateProject}
             isLoading={fsLoading}
          />
      );
  }

  return (
    <div className="h-screen w-screen flex flex-col bg-neutral-950 text-white overflow-hidden font-sans">
      <header className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-neutral-900 shrink-0 z-20">
        <div className="flex items-center gap-4">
           <button onClick={() => setViewMode('launcher')} className="p-2 bg-neutral-800 hover:bg-neutral-700 rounded-lg text-gray-400 hover:text-white transition-colors">
               <Home size={18} />
           </button>
           <div className="flex items-center gap-2">
               <Activity className="text-cyan-400" />
               <h1 className="font-black tracking-tighter text-lg">MIGNA <span className="text-neutral-500 text-xs font-normal">/ {currentProjectName}</span></h1>
           </div>
        </div>

        <div className="flex items-center gap-4">
             {isCaching && <div className="flex items-center gap-1.5 bg-red-950/50 border border-red-500/30 px-2 py-0.5 rounded-full animate-pulse"><div className="w-2 h-2 rounded-full bg-red-500" /><span className="text-[10px] text-red-200 font-bold uppercase">Caching</span></div>}
             {cachedBlob && !isCaching && <div className="flex items-center gap-1.5 bg-green-950/50 border border-green-500/30 px-2 py-0.5 rounded-full"><Zap size={10} className="text-green-400 fill-current" /><span className="text-[10px] text-green-200 font-bold uppercase">Instant Ready</span></div>}
        </div>

        <div className="flex items-center gap-2">
             <div className="flex items-center bg-neutral-800 rounded-md border border-white/5 mr-4">
                  <button onClick={() => { if(confirm("Clear workspace?")) { setData(DEFAULT_LYRICS); setAudioLayers([]); }}} title="Clear" className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-red-400 transition-colors border-r border-white/5"><RotateCcw size={18} /></button>
                  <button onClick={handleSaveProject} disabled={renderStatus.state === 'saving'} title="Save Project" className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-cyan-400 transition-colors disabled:opacity-50">{renderStatus.state === 'saving' ? <Loader2 size={18} className="animate-spin text-cyan-400"/> : <Save size={18} />}</button>
             </div>

             <div className="flex items-center gap-2 bg-neutral-800 p-1 rounded-md border border-white/5">
                 <div className="flex items-center px-1 border-r border-white/5 mr-1">
                     <button onClick={() => setExportMode('normal')} className={`text-[10px] px-2 py-1 font-bold rounded ${exportMode === 'normal' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`}>NORMAL</button>
                     <button onClick={() => setExportMode('alpha')} className={`text-[10px] px-2 py-1 font-bold rounded flex items-center gap-1 ${exportMode === 'alpha' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`} title="Transparent Background (WEBM)">ALPHA</button>
                 </div>
                 {!cachedBlob && exportMode === 'normal' && <select value={exportFormat} onChange={(e) => setExportFormat(e.target.value as any)} className="bg-transparent text-xs font-bold text-gray-300 outline-none px-2 py-1"><option value="mp4">MP4</option><option value="webm">WEBM</option></select>}
                 <button onClick={startRendering} disabled={renderStatus.state !== 'idle'} className={`${cachedBlob && exportMode === 'normal' ? 'bg-green-600 hover:bg-green-500' : 'bg-cyan-600 hover:bg-cyan-500'} disabled:opacity-50 text-white text-xs font-bold px-4 py-1.5 rounded flex items-center gap-2 transition-all`}>
                    {renderStatus.state === 'idle' ? <>{cachedBlob && exportMode === 'normal' ? <Zap size={14} fill="currentColor"/> : <Video size={14} />} {cachedBlob && exportMode === 'normal' ? 'INSTANT' : 'EXPORT'}</> : <><Loader2 size={14} className="animate-spin" /> {renderStatus.state === 'analyzing' ? 'PROCESSING' : renderStatus.state === 'encoding' ? 'ENCODING' : `${Math.round((renderStatus.progress / (renderStatus.totalFrames || 1)) * 100)}%`}</>}
                 </button>
             </div>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
          <div className="w-96 bg-neutral-900 border-r border-white/5 flex flex-col shrink-0 z-10">
              <SettingsPanel 
                 config={rendererConfig} 
                 onUpdate={setRendererConfig}
                 data={data}
                 onUpdateData={setData}
                 currentTime={currentTime}
                 onSeek={handleSeek}
                 onJsonUpload={(j) => setData(JSON.parse(j))}
                 onSrtUpload={(s) => { try { const p = parseSrtToLyricData(s); if(p.segments.length > 0) setData(p); } catch(e){} }}
                 onAudioLayerAdd={handleAudioLayerAdd}
                 audioLayers={audioLayers}
                 onUpdateLayer={updateLayer}
                 onRemoveLayer={removeLayer}
                 onResetProject={() => {}}
                 eventBlocks={eventBlocks}
                 onUpdateEventBlocks={setEventBlocks}
                 onAssetLoaded={handleAssetLoaded}
                 customEffects={customEffects}
                 onUpdateCustomEffects={handleCustomEffectsUpdate}
              />
          </div>

          <div className="flex-1 bg-neutral-950 relative flex flex-col min-w-0">
               <div className={`flex-1 flex items-center justify-center p-8 overflow-hidden ${exportMode === 'alpha' ? 'bg-[conic-gradient(#333_90deg,transparent_90deg)] bg-[length:20px_20px] bg-neutral-800' : 'bg-[radial-gradient(circle_at_center,_#1a1a1a_1px,_transparent_1px)] bg-[length:20px_20px]'}`}>
                   <div className="relative shadow-2xl border border-white/10" style={{ aspectRatio: `${viewportResolution.width/viewportResolution.height}`, height: viewportResolution.width/viewportResolution.height > 1 ? 'auto' : '90%', width: viewportResolution.width/viewportResolution.height > 1 ? '90%' : 'auto', maxHeight: '90%', maxWidth: '90%' }}>
                       <CanvasVideoRenderer ref={rendererRef} data={data} config={rendererConfig} isPlaying={isPlaying} eventBlocks={eventBlocks} customEffects={customEffects} />
                   </div>
               </div>
               <div className="shrink-0 z-20"><Controls isPlaying={isPlaying} onTogglePlay={togglePlay} currentTime={currentTime} duration={duration} onSeek={handleSeek} isRendering={renderStatus.state !== 'idle'} /></div>
          </div>
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { Sliders, LayoutTemplate, Palette, Sparkles, Video, Type, Image as ImageIcon, Upload, Grid, Music, Camera, Aperture, Clock, Plus, Trash2, Monitor, Timer, FolderOpen, FileJson, FileText, FileAudio, Volume2, VolumeX, Mic2, Layers, AlignLeft, Tags, RotateCcw, AlignJustify, Code, Download, BookOpen, Edit2, Play, Check, X } from 'lucide-react';
import { TEMPLATES, FONTS, RESOLUTIONS, TEMPLATE_SHADER_GLSL, TEMPLATE_CAMERA_JS, TEMPLATE_EVENT_PRESET } from '../constants';
import { RendererConfig, AnimationKeyframe, AudioLayer, LyricData, SectionType, SectionStyle, ImageEffect, ProceduralStyle, EventBlock, CustomEffect, CustomEffectType } from '../types';
import { TimelineEditor } from './TimelineEditor';

interface SettingsPanelProps {
  config: RendererConfig;
  onUpdate: (config: RendererConfig) => void;
  // Lyrics Data
  data: LyricData;
  onUpdateData: (data: LyricData) => void;
  // Playback
  currentTime: number;
  onSeek: (time: number) => void;
  // File Handlers
  onJsonUpload: (jsonStr: string) => void;
  onSrtUpload: (srtStr: string) => void;
  onAudioLayerAdd: (file: File) => void;
  // Audio Mixer Handlers
  audioLayers: AudioLayer[];
  onUpdateLayer: (id: string, updates: Partial<AudioLayer>) => void;
  onRemoveLayer: (id: string) => void;
  // Project Management
  onResetProject: () => void;
  // Event Blocks
  eventBlocks: EventBlock[];
  onUpdateEventBlocks: (blocks: EventBlock[]) => void;
  // Asset Management (New)
  onAssetLoaded?: (type: 'background' | 'font', file: File, meta?: string) => void;
  // Custom Effects (New)
  customEffects?: CustomEffect[];
  onUpdateCustomEffects?: (fx: CustomEffect[]) => void;
}

// Helper Components
const ToggleInput: React.FC<{ label: string, value: boolean, onChange: (v: boolean) => void }> = ({ label, value, onChange }) => (
  <div className="flex items-center justify-between">
    <span className="text-sm font-medium text-gray-400">{label}</span>
    <button
      onClick={() => onChange(!value)}
      className={`w-10 h-5 rounded-full relative transition-colors ${value ? 'bg-cyan-600' : 'bg-neutral-700'}`}
    >
      <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${value ? 'translate-x-5' : 'translate-x-0'}`} />
    </button>
  </div>
);

const ColorInput: React.FC<{ label: string, value: string, onChange: (v: string) => void }> = ({ label, value, onChange }) => (
  <div className="flex items-center justify-between bg-neutral-900 p-2 rounded-md border border-white/5">
    <span className="text-xs font-bold text-gray-400">{label}</span>
    <div className="flex items-center gap-2">
      <div className="w-4 h-4 rounded-full border border-white/20" style={{ background: value }}></div>
      <input
        type="color"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="opacity-0 absolute w-8 h-8 cursor-pointer"
      />
      <span className="text-xs font-mono text-gray-500">{value}</span>
    </div>
  </div>
);

export const SettingsPanel: React.FC<SettingsPanelProps> = ({ 
    config, 
    onUpdate, 
    data,
    onUpdateData,
    currentTime,
    onSeek,
    onAudioLayerAdd,
    audioLayers,
    onUpdateLayer,
    onRemoveLayer,
    onJsonUpload,
    onSrtUpload,
    onResetProject,
    eventBlocks,
    onUpdateEventBlocks,
    onAssetLoaded,
    customEffects = [],
    onUpdateCustomEffects
}) => {
  const [activeTab, setActiveTab] = useState<'project' | 'lyrics' | 'sections' | 'templates' | 'customize' | 'library' | 'guide'>('project');
  const [editingEffect, setEditingEffect] = useState<CustomEffect | null>(null);

  const bgInputRef = useRef<HTMLInputElement>(null);
  const fontInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const srtInputRef = useRef<HTMLInputElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);

  const handleTemplateSelect = (template: RendererConfig) => {
    onUpdate(JSON.parse(JSON.stringify(template)));
  };

  const updateNested = (section: keyof RendererConfig, key: string, value: any) => {
    const newConfig = JSON.parse(JSON.stringify(config));
    // @ts-ignore
    newConfig[section][key] = value;
    onUpdate(newConfig);
  };

  const updateSectionStyle = (section: SectionType, key: keyof SectionStyle, value: any) => {
      const newConfig = JSON.parse(JSON.stringify(config));
      if (!newConfig.sectionStyles) newConfig.sectionStyles = {};
      if (!newConfig.sectionStyles[section]) newConfig.sectionStyles[section] = { enabled: false };

      // @ts-ignore
      newConfig.sectionStyles[section][key] = value;
      onUpdate(newConfig);
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const url = URL.createObjectURL(file);
          const type = file.type.startsWith('video') ? 'video' : 'image';

          const newConfig = JSON.parse(JSON.stringify(config));
          newConfig.background.type = type;
          newConfig.background.url = url;
          onUpdate(newConfig);
          if(onAssetLoaded) onAssetLoaded('background', file);
      }
  };

  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
       const reader = new FileReader();
       reader.onload = (ev) => {
           if(ev.target?.result) {
               const fontName = 'CustomFont-' + Date.now();
               const fontFace = new FontFace(fontName, `url(${ev.target.result})`);
               fontFace.load().then((loadedFace) => {
                   document.fonts.add(loadedFace);
                   updateNested('font', 'family', fontName);
                   if(onAssetLoaded) onAssetLoaded('font', file, fontName);
               }).catch(err => console.error("Font load failed", err));
           }
       };
       reader.readAsDataURL(file);
    }
  };

  const handleJsonChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onJsonUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleSrtChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) onSrtUpload(event.target.result as string);
    };
    reader.readAsText(file);
  };

  const handleAudioChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        onAudioLayerAdd(file);
        if (audioInputRef.current) audioInputRef.current.value = '';
    }
  };

  // --- CUSTOM EFFECT HANDLERS ---
  const addNewEffect = (type: CustomEffectType) => {
      const count = customEffects.length + 1;
      const defaultName = type === 'shader' ? `Custom Shader ${count}` : `Camera FX ${count}`;

      const newFx: CustomEffect = {
          id: `fx-${Date.now()}`,
          name: defaultName,
          type,
          code: type === 'shader' ? TEMPLATE_SHADER_GLSL : TEMPLATE_CAMERA_JS,
          active: false,
          description: "New custom effect"
      };

      setEditingEffect(newFx);
  };

  const saveEffect = (fx: CustomEffect) => {
      if (!onUpdateCustomEffects) return;
      const exists = customEffects.find(e => e.id === fx.id);
      let updatedList = [];
      if (exists) {
          updatedList = customEffects.map(e => e.id === fx.id ? fx : e);
      } else {
          updatedList = [...customEffects, fx];
      }
      onUpdateCustomEffects(updatedList);
      setEditingEffect(null);
  };

  const deleteEffect = (id: string) => {
      if (!onUpdateCustomEffects || !confirm("Delete this effect permanently?")) return;
      onUpdateCustomEffects(customEffects.filter(e => e.id !== id));
      if (editingEffect?.id === id) setEditingEffect(null);
  };

  const toggleEffect = (id: string) => {
      if (!onUpdateCustomEffects) return;
      onUpdateCustomEffects(customEffects.map(e => e.id === id ? { ...e, active: !e.active } : e));
  };

  const downloadTemplate = (content: string, filename: string) => {
      const blob = new Blob([content], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
  };

  return (
    <div className="h-full flex flex-col bg-neutral-800 border-r border-white/5 text-gray-200">

      {/* Tab Navigation */}
      <div className="flex border-b border-white/5 bg-neutral-900 overflow-x-auto no-scrollbar">
        {[
            { id: 'project', icon: FolderOpen, label: 'Files' },
            { id: 'lyrics', icon: Clock, label: 'Timeline' },
            { id: 'sections', icon: Tags, label: 'Parts' },
            { id: 'templates', icon: LayoutTemplate, label: 'Presets' },
            { id: 'customize', icon: Sliders, label: 'Style' },
            { id: 'library', icon: Code, label: 'Library' },
            { id: 'guide', icon: BookOpen, label: 'Guide' },
        ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              title={tab.label}
              className={`flex-1 min-w-[50px] py-4 text-[10px] font-bold uppercase flex flex-col items-center justify-center gap-1 transition-colors border-b-2 ${activeTab === tab.id ? 'text-cyan-400 border-cyan-400 bg-white/5' : 'text-gray-500 hover:text-gray-300 border-transparent'}`}
            >
              <tab.icon size={16} />
              {tab.label}
            </button>
        ))}
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar bg-neutral-800">

        {/* PROJECT TAB */}
        {activeTab === 'project' && (
             <div className="p-4 space-y-6">

                {/* Audio Mixer */}
                <section>
                    <div className="flex items-center justify-between mb-3">
                         <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                            <Layers size={14}/> Audio Mixer
                        </h3>
                        <button
                             onClick={() => audioInputRef.current?.click()}
                             className="text-[10px] bg-neutral-700 hover:bg-neutral-600 px-2 py-1 rounded flex items-center gap-1 transition-colors"
                        >
                            <Plus size={10} /> Add Layer
                        </button>
                        <input
                            type="file"
                            ref={audioInputRef}
                            onChange={handleAudioChange}
                            accept="audio/*"
                            className="hidden"
                        />
                    </div>

                    <div className="space-y-2">
                        {audioLayers.length === 0 ? (
                            <div className="text-center p-4 border border-dashed border-white/10 rounded-lg text-xs text-gray-500">
                                No audio tracks loaded.
                            </div>
                        ) : (
                            audioLayers.map(layer => (
                                <div key={layer.id} className="bg-neutral-900 border border-white/5 rounded-lg p-2.5">
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="flex items-center gap-2 overflow-hidden">
                                            <Music size={12} className="text-cyan-500 shrink-0"/>
                                            <span className="text-xs font-bold truncate text-gray-300" title={layer.name}>{layer.name}</span>
                                        </div>
                                        <button 
                                            onClick={() => onRemoveLayer(layer.id)}
                                            className="text-neutral-500 hover:text-red-400 transition-colors"
                                        >
                                            <Trash2 size={12}/>
                                        </button>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <input 
                                            type="range" min="0" max="1" step="0.01"
                                            value={layer.volume}
                                            onChange={(e) => onUpdateLayer(layer.id, { volume: parseFloat(e.target.value) })}
                                            className="flex-1 h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                                            title={`Volume: ${Math.round(layer.volume * 100)}%`}
                                        />
                                        <div className="flex items-center gap-1 shrink-0">
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { muted: !layer.muted })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.muted ? 'bg-red-900/50 border-red-500/50 text-red-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Mute"
                                            >
                                                M
                                            </button>
                                            <button
                                                onClick={() => onUpdateLayer(layer.id, { solo: !layer.solo })}
                                                className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border transition-colors ${layer.solo ? 'bg-yellow-900/50 border-yellow-500/50 text-yellow-400' : 'bg-neutral-800 border-white/5 text-gray-400 hover:text-white'}`}
                                                title="Solo"
                                            >
                                                S
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
