// --- INDEXED DB HELPER ---
const DB_NAME = 'AppMignaDB';
const DB_VERSION = 1;

const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains('projects')) db.createObjectStore('projects', { keyPath: 'name' });
      if (!db.objectStoreNames.contains('shaders')) db.createObjectStore('shaders', { keyPath: 'id' });
      if (!db.objectStoreNames.contains('renders')) db.createObjectStore('renders', { keyPath: 'name' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const dbGetAllKeys = (db: IDBDatabase, storeName: string): Promise<string[]> => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readonly');
        const store = transaction.objectStore(storeName);
        const request = store.getAllKeys();
        request.onsuccess = () => resolve(request.result as string[]);
        request.onerror = () => reject(request.error);
    });
};

const dbGet = (db: IDBDatabase, storeName: string, key: string): Promise<any> => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readonly');
        const store = transaction.objectStore(storeName);
        const request = store.get(key);
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
};

const dbPut = (db: IDBDatabase, storeName: string, value: any): Promise<void> => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        const request = store.put(value);
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
    });
};

// Helper: Convert Blob to Base64
const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      resolve(result);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

// Helper: Convert Base64 to Blob
const base64ToBlob = async (base64: string): Promise<Blob> => {
  const res = await fetch(base64);
  return res.blob();
};

const parseSrtTimestamp = (timestamp: string): number => {
  if (!timestamp) return 0;
  const normalized = timestamp.replace(',', '.').trim();
  const parts = normalized.split(':');
  if (parts.length < 3) return 0; 
  const hours = parseFloat(parts[0]);
  const minutes = parseFloat(parts[1]);
  const seconds = parseFloat(parts[2]);
  return (hours * 3600) + (minutes * 60) + seconds;
};

const parseSrtToLyricData = (srtContent: string): LyricData => {
  const normalizedContent = srtContent.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const blocks = normalizedContent.trim().split(/\n\s*\n/);
  const segments: Segment[] = [];

  blocks.forEach((block, index) => {
    const lines = block.split('\n');
    if (lines.length < 2) return;
    let timeLineIndex = lines.findIndex(l => l.includes('-->'));
    if (timeLineIndex === -1) return;
    const timeLine = lines[timeLineIndex];
    const [startStr, endStr] = timeLine.split('-->');
    if (!startStr || !endStr) return;
    const start = parseSrtTimestamp(startStr);
    const end = parseSrtTimestamp(endStr);
    const textLines = lines.slice(timeLineIndex + 1).map(l => l.replace(/<[^>]*>/g, '').trim()).filter(l => l.length > 0);
    const fullText = textLines.join(' ');
    if (!fullText) return;
    const words: Word[] = [];
    const totalDuration = end - start;
    let allWords: {text: string, line: number}[] = [];
    textLines.forEach((line, lineIdx) => {
        const lineWords = line.split(/\s+/);
        lineWords.forEach(w => allWords.push({ text: w, line: lineIdx }));
    });
    const wordDuration = totalDuration / allWords.length;
    allWords.forEach((wObj, i) => {
      words.push({ word: wObj.text, start: start + (i * wordDuration), end: start + ((i + 1) * wordDuration), probability: 1.0, line_number: wObj.line });
    });
    segments.push({ id: index.toString(), start, end, text: fullText, section: 'verse', words });
  });
  return { segments };
};

const extractAudioAnalysis = (audioBuffer: AudioBuffer, fps: number, duration: number): AudioVisualizerData[] => {
    if (!duration || duration <= 0 || !Number.isFinite(duration)) return [];
    const totalFrames = Math.ceil(duration * fps);
    const result: AudioVisualizerData[] = new Array(totalFrames);
    const rawData = audioBuffer.getChannelData(0); 
    const sampleRate = audioBuffer.sampleRate;
    const samplesPerFrame = Math.floor(sampleRate / fps);
    const fftSize = 256;
    const frequencyBinCount = fftSize / 2;
    for (let i = 0; i < totalFrames; i++) {
        const startSample = i * samplesPerFrame;
        const endSample = Math.min(startSample + samplesPerFrame, rawData.length);
        let sum = 0; let diffSum = 0; let highFreqSum = 0;
        for (let j = startSample; j < endSample; j++) {
            const val = rawData[j]; sum += val * val; 
            if (j > startSample) { const diff = val - rawData[j-1]; diffSum += diff * diff; 
                if (j > startSample + 1) { const diff2 = (val - rawData[j-1]) - (rawData[j-1] - rawData[j-2]); highFreqSum += diff2 * diff2; } }
        }
        const rms = Math.sqrt(sum / (endSample - startSample)) || 0;
        const diffRms = Math.sqrt(diffSum / (endSample - startSample)) || 0;
        const highRms = Math.sqrt(highFreqSum / (endSample - startSample)) || 0;
        const bass = Math.min(1, rms * 4); const mid = Math.min(1, diffRms * 8); const high = Math.min(1, highRms * 16);
        const dataArray = new Uint8Array(frequencyBinCount);
        const bassBins = 10; const midBins = 90;
        for(let k=0; k<frequencyBinCount; k++) {
            if (k < bassBins) dataArray[k] = bass * 255;
            else if (k < bassBins + midBins) dataArray[k] = mid * 255;
            else dataArray[k] = high * 255;
        }
        result[i] = { bass, mid, high, raw: dataArray };
    }
    return result;
};

export default function App() {
  // --- APP STATE ---
  const [viewMode, setViewMode] = useState<'launcher' | 'editor'>('launcher');

  // Database State
  const [db, setDb] = useState<IDBDatabase | null>(null);
  const [projectsList, setProjectsList] = useState<string[]>([]);
  const [fsLoading, setFsLoading] = useState(true);
  const [currentProjectName, setCurrentProjectName] = useState<string>('Untitled');

  // Editor State
  const [data, setData] = useState<LyricData>(DEFAULT_LYRICS);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [eventBlocks, setEventBlocks] = useState<EventBlock[]>([]);
  const [audioLayers, setAudioLayers] = useState<AudioLayer[]>([]);
  const [customEffects, setCustomEffects] = useState<CustomEffect[]>([]);
  const [assets, setAssets] = useState<LoadedAsset[]>([]); // New: Asset Library

  const backgroundFileRef = useRef<{ file: Blob, type: 'image' | 'video' } | null>(null);
  const fontFilesRef = useRef<Map<string, Blob>>(new Map());
  const [renderStatus, setRenderStatus] = useState<RenderStatus>({ state: 'idle', progress: 0 });
  const [audioVisualizerData, setAudioVisualizerData] = useState<AudioVisualizerData>({ bass: 0, mid: 0, high: 0, raw: new Uint8Array() });
  const [rendererConfig, setRendererConfig] = useState<RendererConfig>(TEMPLATES[0]);
  const [exportFormat, setExportFormat] = useState<'webm' | 'mp4'>('mp4');
  const [exportMode, setExportMode] = useState<'normal' | 'alpha'>('normal');
  const [cachedBlob, setCachedBlob] = useState<Blob | null>(null);
  const [isCaching, setIsCaching] = useState(false);

  // Refs
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const audioDestinationRef = useRef<MediaStreamAudioDestinationNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourcesRef = useRef<Map<string, AudioBufferSourceNode>>(new Map());
  const gainsRef = useRef<Map<string, GainNode>>(new Map());
  const rendererRef = useRef<CanvasVideoRendererRef>(null);
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // --- INITIALIZE DB ---
  useEffect(() => {
      const init = async () => {
          try {
              const database = await openDB();
              setDb(database);
              await refreshProjectsList(database);

              // Load Shaders
              const transaction = database.transaction(['shaders'], 'readonly');
              const store = transaction.objectStore('shaders');
              const request = store.getAll();
              request.onsuccess = () => {
                  if (request.result && request.result.length > 0) {
                      setCustomEffects(request.result);
                  }
              };
          } catch(e) {
              console.error("DB Error", e);
          } finally {
              setFsLoading(false);
          }
      };
      init();
  }, []);

  const refreshProjectsList = async (database: IDBDatabase) => {
      const keys = await dbGetAllKeys(database, 'projects');
      setProjectsList(keys);
  };

  // --- LAUNCHER ACTIONS ---

  const handleCreateProject = (type: AppProjectType, name: string) => {
      // Reset State
      setData(DEFAULT_LYRICS);
      setRendererConfig(TEMPLATES[0]);
      setAudioLayers([]);
      setEventBlocks([]);
      setCachedBlob(null);
      setAssets([]);
      backgroundFileRef.current = null;
      fontFilesRef.current.clear();
      setCurrentProjectName(name);
      setViewMode('editor');
  };

  const handleLoadProjectFromDisk = async (name: string) => {
      if (!db) return;
      setFsLoading(true);
      try {
          const project = await dbGet(db, 'projects', name) as ProjectFile;
          if (!project) throw new Error("Project not found");

          // Restore State
          setCurrentProjectName(project.name);
          if (project.lyricData) setData(project.lyricData);
          if (project.config) setRendererConfig(project.config);
          if (project.eventBlocks) setEventBlocks(project.eventBlocks);

          // Merge custom effects 
          if (project.customEffects) {
              setCustomEffects(prev => {
                  const combined = [...prev];
                  project.customEffects?.forEach(pFx => {
                      if (!combined.find(c => c.id === pFx.id)) combined.push(pFx);
                  });
                  return combined;
              });
          }

          // Restore Assets
          if (project.assets) {
              initAudioEngine();
              const restoredLayers: AudioLayer[] = [];
              for (const audioAsset of project.assets.audio) {
                  const blob = await base64ToBlob(audioAsset.data);
                  const arrayBuffer = await blob.arrayBuffer();
                  const audioBuffer = await audioContextRef.current!.decodeAudioData(arrayBuffer);
                  restoredLayers.push({
                      id: audioAsset.id, name: audioAsset.name, buffer: audioBuffer,
                      volume: audioAsset.volume, muted: audioAsset.muted, solo: audioAsset.solo,
                      duration: audioBuffer.duration, sourceFile: blob, mimeType: audioAsset.mimeType
                  });
              }
              setAudioLayers(restoredLayers);
              if (restoredLayers.length > 0) setDuration(Math.max(...restoredLayers.map(l => l.duration)));

              const loadedAssetsList: LoadedAsset[] = [];

              if (project.assets.background) {
                  const blob = await base64ToBlob(project.assets.background.data);
                  const url = URL.createObjectURL(blob);
                  backgroundFileRef.current = { file: blob, type: project.assets.background.type };
                  setRendererConfig(prev => ({ ...prev, background: { ...prev.background, type: project.assets.background!.type, url: url } }));

                  // Add to assets library
                  loadedAssetsList.push({
                      id: 'bg-' + Date.now(),
                      type: project.assets.background.type,
                      name: 'Restored Background',
                      url,
                      file: blob,
                      mimeType: project.assets.background.mimeType
                  });
              }

              for (const fontAsset of project.assets.fonts) {
                  const blob = await base64ToBlob(fontAsset.data);
                  fontFilesRef.current.set(fontAsset.name, blob);
                  const url = URL.createObjectURL(blob);
                  const fontFace = new FontFace(fontAsset.name, `url(${url})`);
                  try { const loaded = await fontFace.load(); document.fonts.add(loaded); } catch(e) {}

                  // Add to assets library
                  loadedAssetsList.push({
                      id: 'font-' + fontAsset.name,
                      type: 'font',
                      name: fontAsset.name,
                      url,
                      file: blob,
                      mimeType: fontAsset.mimeType
                  });
              }

              setAssets(loadedAssetsList);
          }
          setViewMode('editor');
      } catch (e) {
          console.error(e);
          alert("Failed to load project.");
      } finally {
          setFsLoading(false);
      }
  };

  const handleImportProject = async (file: File) => {
      if (!db) return;
      try {
          const text = await file.text();
          const project = JSON.parse(text);

          if (!project.name || !project.version) {
             throw new Error("Invalid project structure");
          }

          await dbPut(db, 'projects', project);
          await refreshProjectsList(db);
          alert(`Project "${project.name}" imported successfully!`);
      } catch (e) {
          console.error("Import failed", e);
          alert("Failed to import project file. Ensure it is a valid .json project.");
      }
  };

  const handleCustomEffectsUpdate = (fx: CustomEffect[]) => {
      setCustomEffects(fx);
      if (db) {
          // Save updated/new effects to DB
          fx.forEach(effect => dbPut(db, 'shaders', effect));
      }
  };

  // --- APP LOGIC (Mixer, Playback, Render) ---
  const initAudioEngine = () => {
      if (!audioContextRef.current) {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          const ctx = new AudioContext();
          audioContextRef.current = ctx;
          const masterGain = ctx.createGain();
          masterGain.connect(ctx.destination);
          masterGainRef.current = masterGain;
          const dest = ctx.createMediaStreamDestination();
          masterGain.connect(dest);
          audioDestinationRef.current = dest;
          const analyser = ctx.createAnalyser();
          analyser.fftSize = 256;
          masterGain.connect(analyser); 
          analyserRef.current = analyser;
      } else if (audioContextRef.current.state === 'suspended') {
          audioContextRef.current.resume();
      }
  };

  useEffect(() => { if (cachedBlob) setCachedBlob(null); }, [data, rendererConfig, audioLayers, eventBlocks, customEffects]);

  const handleAudioLayerAdd = async (file: File) => {
      initAudioEngine();
      if (!audioContextRef.current) return;
      try {
          const arrayBuffer = await file.arrayBuffer();
          const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);
          const newLayer: AudioLayer = {
              id: Date.now().toString() + Math.random().toString(),
              name: file.name, buffer: audioBuffer, volume: 1.0, muted: false, solo: false,
              duration: audioBuffer.duration, sourceFile: file, mimeType: file.type
          };
          setAudioLayers(prev => {
              const updated = [...prev, newLayer];
              setDuration(Math.max(...updated.map(l => l.duration)));
              return updated;
          });
      } catch (e) { console.error(e); alert("Failed to load audio"); }
  };

  const updateLayer = (id: string, updates: Partial<AudioLayer>) => {
      setAudioLayers(prev => prev.map(l => l.id === id ? { ...l, ...updates } : l));
  };
  const removeLayer = (id: string) => {
      setAudioLayers(prev => {
          const updated = prev.filter(l => l.id !== id);
          const maxDur = Math.max(...updated.map(l => l.duration), 0);
          setDuration(maxDur);
          return updated;
      });
  };

  const handleAssetLoaded = (type: 'background' | 'font', file: File, meta?: string) => {
      // Add to Library
      const url = URL.createObjectURL(file);

      let assetType: 'image' | 'video' | 'font' = 'image';
      if (type === 'font') {
          assetType = 'font';
      } else {
          assetType = file.type.startsWith('video') ? 'video' : 'image';
      }

      const newAsset: LoadedAsset = {
          id: `asset-${Date.now()}-${Math.random()}`,
          type: assetType,
          name: file.name,
          url,
          file,
          mimeType: file.type
      };
      setAssets(prev => [...prev, newAsset]);

      // Apply
      if (type === 'background') {
          backgroundFileRef.current = { file, type: assetType === 'video' ? 'video' : 'image' };
          // NOTE: Config update happens in SettingsPanel handler usually, but here we ensure Ref is set
      }
      else if (type === 'font' && meta) fontFilesRef.current.set(meta, file);
  };

  const handleSelectAsset = (asset: LoadedAsset) => {
      if (asset.type === 'image' || asset.type === 'video') {
          const newType = asset.type;
          backgroundFileRef.current = { file: asset.file, type: newType };
          setRendererConfig(prev => ({
              ...prev,
              background: {
                  ...prev.background,
                  type: newType,
                  url: asset.url
              }
          }));
      }
      // For fonts, we don't auto-apply because they are selected via dropdown by name.
      // But they are available in the system now.
  };

  useEffect(() => {
     if (!audioContextRef.current) return;
     const hasSolo = audioLayers.some(l => l.solo);
     audioLayers.forEach(layer => {
         if (!gainsRef.current.has(layer.id)) {
             const g = audioContextRef.current!.createGain();
             if (masterGainRef.current) g.connect(masterGainRef.current);
             gainsRef.current.set(layer.id, g);
         }
         const gainNode = gainsRef.current.get(layer.id);
         if (gainNode) {
             const effectiveMute = layer.muted || (hasSolo && !layer.solo);
             gainNode.gain.setTargetAtTime(effectiveMute ? 0 : layer.volume, audioContextRef.current!.currentTime, 0.05);
         }
     });
     gainsRef.current.forEach((val, key) => { if (!audioLayers.find(l => l.id === key)) { val.disconnect(); gainsRef.current.delete(key); } });
  }, [audioLayers]);

  const stopAllSources = () => { sourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} s.disconnect(); }); sourcesRef.current.clear(); };
  const startAllSources = (offset: number) => {
      if (!audioContextRef.current) return;
      stopAllSources();
      audioLayers.forEach(layer => {
          const source = audioContextRef.current!.createBufferSource();
          source.buffer = layer.buffer;
          const gain = gainsRef.current.get(layer.id);
          if (gain) source.connect(gain);
          source.start(0, offset);
          sourcesRef.current.set(layer.id, source);
      });
  };

  const startRecordingCache = () => {
      if (!rendererRef.current?.canvas || !audioDestinationRef.current) return;
      try {
          const combined = new MediaStream([...rendererRef.current.canvas.captureStream(60).getVideoTracks(), ...audioDestinationRef.current.stream.getAudioTracks()]);
          const recorder = new MediaRecorder(combined, { mimeType: 'video/webm;codecs=vp9', videoBitsPerSecond: 8000000 });
          recordedChunksRef.current = [];
          recorder.ondataavailable = (e) => { if (e.data.size > 0) recordedChunksRef.current.push(e.data); };
          recorder.start();
          mediaRecorderRef.current = recorder;
          setIsCaching(true);
      } catch (err) {}
  };

  const stopRecordingCache = (save: boolean) => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();
          if (save && recordedChunksRef.current.length > 0) setCachedBlob(new Blob(recordedChunksRef.current, { type: 'video/webm' }));
      }
      setIsCaching(false); mediaRecorderRef.current = null;
  };

  const togglePlay = () => {
    initAudioEngine();
    if (!audioContextRef.current) return;
    if (isPlaying) {
      if (isCaching) stopRecordingCache(false);
      audioContextRef.current.suspend();
      setIsPlaying(false);
    } else {
      audioContextRef.current.resume();
      if (sourcesRef.current.size === 0) {
          if (currentTime < 0.1) { setCachedBlob(null); startRecordingCache(); }
          startAllSources(currentTime);
          startTimeRef.current = audioContextRef.current.currentTime - currentTime;
      }
      setIsPlaying(true);
    }
  };

  const handleSeek = (time: number) => {
      if (!audioContextRef.current) return;
      if (isCaching) stopRecordingCache(false);
      const wasPlaying = isPlaying;
      audioContextRef.current.suspend();
      stopAllSources();
      setCurrentTime(time);
      startTimeRef.current = audioContextRef.current.currentTime - time;
      if (wasPlaying) { startAllSources(time); audioContextRef.current.resume(); }
  };

  const analyzeAudio = () => {
    if (analyserRef.current) {
      const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
      analyserRef.current.getByteFrequencyData(dataArray);
      const avg = (arr: Uint8Array) => arr.reduce((a, b) => a + b, 0) / arr.length;
      setAudioVisualizerData({ bass: avg(dataArray.slice(0, 10)) / 255, mid: avg(dataArray.slice(10, 100)) / 255, high: avg(dataArray.slice(100, 200)) / 255, raw: dataArray });
    }
  };

  const loop = () => {
    if (isPlaying && audioContextRef.current) {
        let syncedTime = audioContextRef.current.currentTime - startTimeRef.current;
        if (syncedTime >= duration && duration > 0) { syncedTime = duration; if (isCaching) stopRecordingCache(true); setIsPlaying(false); stopAllSources(); audioContextRef.current.suspend(); }
        setCurrentTime(syncedTime); analyzeAudio();
    }
    if (rendererRef.current) rendererRef.current.drawFrame(currentTime, audioVisualizerData, false);
    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => { requestRef.current = requestAnimationFrame(loop); return () => cancelAnimationFrame(requestRef.current); }, [currentTime, audioVisualizerData, isPlaying, duration, isCaching]);

  const handleSaveProject = async () => {
      setRenderStatus({ state: 'saving', progress: 0 });
      try {
          const audioAssets = await Promise.all(audioLayers.map(async (layer) => {
              if (layer.sourceFile) return { id: layer.id, name: layer.name, mimeType: layer.mimeType || 'audio/mp3', data: await blobToBase64(layer.sourceFile), volume: layer.volume, muted: layer.muted, solo: layer.solo };
              return null;
          }));
          let backgroundAsset = undefined;
          if (rendererConfig.background.type !== 'procedural' && rendererConfig.background.type !== 'solid' && backgroundFileRef.current) {
              backgroundAsset = { type: backgroundFileRef.current.type, mimeType: backgroundFileRef.current.file.type, data: await blobToBase64(backgroundFileRef.current.file) };
          }
          const fontAssets = await Promise.all(Array.from(fontFilesRef.current.entries()).map(async ([name, blob]) => ({ name, mimeType: blob.type, data: await blobToBase64(blob) })));

          const project: ProjectFile = {
              version: '1.3',
              type: 'video-lyrics',
              timestamp: Date.now(),
              name: currentProjectName,
              lyricData: data,
              config: rendererConfig,
              eventBlocks: eventBlocks,
              assets: { audio: audioAssets.filter(a => a !== null) as any, background: backgroundAsset, fonts: fontAssets },
              customEffects: customEffects
          };

          const jsonString = JSON.stringify(project);

          if (db) {
              // Save to Internal DB
              await dbPut(db, 'projects', project);
              alert("Project saved to internal storage!");
              await refreshProjectsList(db);
          } else {
              // Fallback Download
              const blob = new Blob([jsonString], { type: 'application/json' });
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `${currentProjectName}.json`;
              a.click();
              URL.revokeObjectURL(url);
          }
      } catch (e) { console.error("Save Error:", e); alert("Failed to save project."); } 
      finally { setRenderStatus({ state: 'idle', progress: 0 }); }
  };

  const startRendering = async () => {
    if (audioLayers.length === 0) return alert("No audio layers.");
    if (renderStatus.state !== 'idle') return;
    const resConfig = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];
    setRenderStatus({ state: 'analyzing', progress: 0 });
    if (isPlaying && audioContextRef.current) { audioContextRef.current.suspend(); setIsPlaying(false); }

    try {
      const sampleRate = 44100; const FPS = 30; const totalFrames = Math.ceil(duration * FPS);
      const offlineCtx = new OfflineAudioContext(2, Math.ceil(Math.max(0.1, duration) * sampleRate), sampleRate);
      const offlineMaster = offlineCtx.createGain(); offlineMaster.connect(offlineCtx.destination);
      audioLayers.forEach(l => { if (l.muted || (audioLayers.some(al=>al.solo) && !l.solo)) return; const s = offlineCtx.createBufferSource(); s.buffer = l.buffer; const g = offlineCtx.createGain(); g.gain.value = l.volume; s.connect(g); g.connect(offlineMaster); s.start(0); });
      const renderedBuffer = await offlineCtx.startRendering();
      const analysisFrames = extractAudioAnalysis(renderedBuffer, FPS, duration);
      setRenderStatus({ state: 'rendering', progress: 0, totalFrames });
      const format = exportMode === 'alpha' ? 'webm' : exportFormat;
      let muxer = format === 'mp4' ? new Mp4Muxer({ target: new Mp4ArrayBufferTarget(), video: { codec: 'avc', width: resConfig.width, height: resConfig.height }, audio: { codec: 'aac', numberOfChannels: 2, sampleRate }, fastStart: 'in-memory' }) : new WebMMuxer({ target: new WebMArrayBufferTarget(), video: { codec: 'V_VP9', width: resConfig.width, height: resConfig.height, frameRate: FPS, alpha: exportMode === 'alpha' }, audio: { codec: 'A_OPUS', numberOfChannels: 2, sampleRate } });
      const vEnc = new VideoEncoder({ output: (c, m) => muxer.addVideoChunk(c, m), error: (e) => console.error(e) });
      await vEnc.configure({ codec: format === 'mp4' ? 'avc1.4d002a' : 'vp09.00.10.08', width: resConfig.width, height: resConfig.height, bitrate: 1e7, alpha: exportMode === 'alpha' ? 'keep' : 'discard' });
      const canvas = rendererRef.current?.canvas;
      if (!canvas) throw new Error("No Canvas");
      for (let i = 0; i < totalFrames; i++) {
         const t = i / FPS;
         if (rendererRef.current?.seekToTime) await rendererRef.current.seekToTime(t);
         rendererRef.current?.drawFrame(t, analysisFrames[i] || {bass:0,mid:0,high:0,raw:new Uint8Array(128)}, exportMode === 'alpha');
         const frame = new VideoFrame(canvas, { timestamp: t * 1e6, alpha: exportMode === 'alpha' ? 'keep' : 'discard' });
         if (vEnc.encodeQueueSize > 5) await vEnc.flush();
         vEnc.encode(frame, { keyFrame: i % (FPS * 2) === 0 });
         frame.close();
         if (i % 10 === 0) { setRenderStatus(prev => ({ ...prev, progress: i })); await new Promise(r => setTimeout(r, 0)); }
      }
      setRenderStatus({ state: 'encoding', progress: 100 });
      await vEnc.flush(); vEnc.close();
      const aEnc = new AudioEncoder({ output: (c, m) => muxer.addAudioChunk(c, m), error: console.error });
      aEnc.configure({ codec: format === 'mp4' ? 'mp4a.40.2' : 'opus', numberOfChannels: 2, sampleRate });
      const c0 = renderedBuffer.getChannelData(0); const c1 = renderedBuffer.numberOfChannels > 1 ? renderedBuffer.getChannelData(1) : c0;
      for (let i = 0; i < renderedBuffer.length; i += 4096) {
          const len = Math.min(4096, renderedBuffer.length - i);
          const d = new Float32Array(len * 2);
          for (let j = 0; j < len; j++) { d[j*2] = c0[i+j]; d[j*2+1] = c1[i+j]; }
          const ad = new AudioData({ format: 'f32', sampleRate, numberOfFrames: len, numberOfChannels: 2, timestamp: i / sampleRate * 1e6, data: d });
          aEnc.encode(ad); ad.close();
      }
      await aEnc.flush(); aEnc.close();
      muxer.finalize();
      const blob = new Blob([muxer.target.buffer], { type: format === 'mp4' ? 'video/mp4' : 'video/webm' });

      // Save Logic
      if (db) {
          const fileName = `${currentProjectName}_render.${format}`;
          await dbPut(db, 'renders', { name: fileName, blob, date: new Date() });
          // Also Download automatically as it is a final render
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a'); a.href = url; a.download = `render.${format}`; a.click();
      } else {
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a'); a.href = url; a.download = `render.${format}`; a.click();
      }
      setRenderStatus({ state: 'done', progress: 100 });
      setTimeout(() => setRenderStatus({ state: 'idle', progress: 0 }), 3000);
    } catch (e) { console.error(e); setRenderStatus({ state: 'idle', progress: 0 }); alert("Render Failed"); }
  };

  const viewportResolution = RESOLUTIONS.find(r => r.id === rendererConfig.resolutionId) || RESOLUTIONS[0];

  // --- RENDER ---

  if (viewMode === 'launcher') {
      return (
          <ProjectLauncher 
             workspaceName={db ? "AppMignaDB (Internal)" : "Connecting..."}
             projects={projectsList}
             onLoadProject={handleLoadProjectFromDisk}
             onCreateProject={handleCreateProject}
             onImportProject={handleImportProject}
             isLoading={fsLoading}
          />
      );
  }

  return (
    <div className="h-screen w-screen flex flex-col bg-neutral-950 text-white overflow-hidden font-sans">
      <header className="h-14 border-b border-white/10 flex items-center justify-between px-4 bg-neutral-900 shrink-0 z-20">
        <div className="flex items-center gap-4">
           <button onClick={() => setViewMode('launcher')} className="p-2 bg-neutral-800 hover:bg-neutral-700 rounded-lg text-gray-400 hover:text-white transition-colors">
               <Home size={18} />
           </button>
           <div className="flex items-center gap-2">
               <Activity className="text-cyan-400" />
               <h1 className="font-black tracking-tighter text-lg">MIGNA <span className="text-neutral-500 text-xs font-normal">/ {currentProjectName}</span></h1>
           </div>
        </div>

        <div className="flex items-center gap-4">
             {isCaching && <div className="flex items-center gap-1.5 bg-red-950/50 border border-red-500/30 px-2 py-0.5 rounded-full animate-pulse"><div className="w-2 h-2 rounded-full bg-red-500" /><span className="text-[10px] text-red-200 font-bold uppercase">Caching</span></div>}
             {cachedBlob && !isCaching && <div className="flex items-center gap-1.5 bg-green-950/50 border border-green-500/30 px-2 py-0.5 rounded-full"><Zap size={10} className="text-green-400 fill-current" /><span className="text-[10px] text-green-200 font-bold uppercase">Instant Ready</span></div>}
        </div>

        <div className="flex items-center gap-2">
             <div className="flex items-center bg-neutral-800 rounded-md border border-white/5 mr-4">
                  <button onClick={() => { if(confirm("Clear workspace?")) { setData(DEFAULT_LYRICS); setAudioLayers([]); }}} title="Clear" className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-red-400 transition-colors border-r border-white/5"><RotateCcw size={18} /></button>
                  <button onClick={handleSaveProject} disabled={renderStatus.state === 'saving'} title="Save Project" className="p-2 hover:bg-neutral-700 text-gray-400 hover:text-cyan-400 transition-colors disabled:opacity-50">{renderStatus.state === 'saving' ? <Loader2 size={18} className="animate-spin text-cyan-400"/> : <Save size={18} />}</button>
             </div>

             <div className="flex items-center gap-2 bg-neutral-800 p-1 rounded-md border border-white/5">
                 <div className="flex items-center px-1 border-r border-white/5 mr-1">
                     <button onClick={() => setExportMode('normal')} className={`text-[10px] px-2 py-1 font-bold rounded ${exportMode === 'normal' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`}>NORMAL</button>
                     <button onClick={() => setExportMode('alpha')} className={`text-[10px] px-2 py-1 font-bold rounded flex items-center gap-1 ${exportMode === 'alpha' ? 'bg-neutral-600 text-white' : 'text-gray-400 hover:text-white'}`} title="Transparent Background (WEBM)">ALPHA</button>
                 </div>
                 {!cachedBlob && exportMode === 'normal' && <select value={exportFormat} onChange={(e) => setExportFormat(e.target.value as any)} className="bg-transparent text-xs font-bold text-gray-300 outline-none px-2 py-1"><option value="mp4">MP4</option><option value="webm">WEBM</option></select>}
                 <button onClick={startRendering} disabled={renderStatus.state !== 'idle'} className={`${cachedBlob && exportMode === 'normal' ? 'bg-green-600 hover:bg-green-500' : 'bg-cyan-600 hover:bg-cyan-500'} disabled:opacity-50 text-white text-xs font-bold px-4 py-1.5 rounded flex items-center gap-2 transition-all`}>
                    {renderStatus.state === 'idle' ? <>{cachedBlob && exportMode === 'normal' ? <Zap size={14} fill="currentColor"/> : <Video size={14} />} {cachedBlob && exportMode === 'normal' ? 'INSTANT' : 'EXPORT'}</> : <><Loader2 size={14} className="animate-spin" /> {renderStatus.state === 'analyzing' ? 'PROCESSING' : renderStatus.state === 'encoding' ? 'ENCODING' : `${Math.round((renderStatus.progress / (renderStatus.totalFrames || 1)) * 100)}%`}</>}
                 </button>
             </div>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
          <div className="w-96 bg-neutral-900 border-r border-white/5 flex flex-col shrink-0 z-10">
              <SettingsPanel 
                 config={rendererConfig} 
                 onUpdate={setRendererConfig}
                 data={data}
                 onUpdateData={setData}
                 currentTime={currentTime}
                 onSeek={handleSeek}
                 onJsonUpload={(j) => setData(JSON.parse(j))}
                 onSrtUpload={(s) => { try { const p = parseSrtToLyricData(s); if(p.segments.length > 0) setData(p); } catch(e){} }}
                 onAudioLayerAdd={handleAudioLayerAdd}
                 audioLayers={audioLayers}
                 onUpdateLayer={updateLayer}
                 onRemoveLayer={removeLayer}
                 onResetProject={() => {}}
                 eventBlocks={eventBlocks}
                 onUpdateEventBlocks={setEventBlocks}
                 onAssetLoaded={handleAssetLoaded}
                 customEffects={customEffects}
                 onUpdateCustomEffects={handleCustomEffectsUpdate}
                 assets={assets}
                 onSelectAsset={handleSelectAsset}
              />
          </div>

          <div className="flex-1 bg-neutral-950 relative flex flex-col min-w-0">
               <div className={`flex-1 flex items-center justify-center p-8 overflow-hidden ${exportMode === 'alpha' ? 'bg-[conic-gradient(#333_90deg,transparent_90deg)] bg-[length:20px_20px] bg-neutral-800' : 'bg-[radial-gradient(circle_at_center,_#1a1a1a_1px,_transparent_1px)] bg-[length:20px_20px]'}`}>
                   <div className="relative shadow-2xl border border-white/10" style={{ aspectRatio: `${viewportResolution.width/viewportResolution.height}`, height: viewportResolution.width/viewportResolution.height > 1 ? 'auto' : '90%', width: viewportResolution.width/viewportResolution.height > 1 ? '90%' : 'auto', maxHeight: '90%', maxWidth: '90%' }}>
                       <CanvasVideoRenderer ref={rendererRef} data={data} config={rendererConfig} isPlaying={isPlaying} eventBlocks={eventBlocks} customEffects={customEffects} />
                   </div>
               </div>
               <div className="shrink-0 z-20"><Controls isPlaying={isPlaying} onTogglePlay={togglePlay} currentTime={currentTime} duration={duration} onSeek={handleSeek} isRendering={renderStatus.state !== 'idle'} /></div>
          </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { LyricData, Segment, Word, EventBlock, EffectOverrides, CustomEffect, RendererConfig } from '../types';
import { Clock, Trash2, Plus, PlayCircle, Download, AlertCircle, ChevronDown, ChevronUp, Tag, X, FolderInput, Check, Zap, Eye, EyeOff, TrendingUp, TrendingDown, Palette, Type, MousePointer2, ArrowDownCircle } from 'lucide-react';

interface TimelineEditorProps {
  data: LyricData;
  onUpdate: (data: LyricData) => void;
  currentTime: number;
  onSeek: (time: number) => void;
  eventBlocks: EventBlock[];
  onUpdateEventBlocks: (blocks: EventBlock[]) => void;
  customEffects?: CustomEffect[]; 
  projectConfig?: RendererConfig; // Need access to project colors for the palette
  duration?: number;
}

// --- HELPER FUNCTIONS ---

const secondsToMMSS = (seconds: number): string => {
  const m = Math.floor(seconds / 60);
  const s = (seconds % 60).toFixed(2);
  const sStr = s.includes('.') ? s : `${s}.00`;
  return `${m.toString().padStart(2, '0')}:${sStr.padStart(5, '0')}`;
};

const mmssToSeconds = (timeStr: string): number => {
  const parts = timeStr.split(':');
  if (parts.length === 2) {
    const minutes = parseInt(parts[0], 10);
    const seconds = parseFloat(parts[1]);
    return (minutes * 60) + seconds;
  }
  return parseFloat(timeStr) || 0;
};

// Recalculates word timings linearly across the segment duration
const recalculateWords = (text: string, start: number, end: number): Word[] => {
  const lines = text.split('\n');
  const words: Word[] = [];
  const duration = Math.max(0.1, end - start);

  let totalWordCount = 0;
  lines.forEach(line => {
    totalWordCount += line.trim().split(/\s+/).filter(w => w.length > 0).length;
  });

  if (totalWordCount === 0) return [];

  const timePerWord = duration / totalWordCount;
  let currentWordIndex = 0;

  lines.forEach((line, lineIdx) => {
    const lineWords = line.trim().split(/\s+/).filter(w => w.length > 0);
    lineWords.forEach((w) => {
      const wordStart = start + (currentWordIndex * timePerWord);
      const wordEnd = wordStart + timePerWord;
      words.push({
        word: w,
        start: wordStart,
        end: wordEnd,
        probability: 1,
        line_number: lineIdx
      });
      currentWordIndex++;
    });
  });

  return words;
};

// --- SUB-COMPONENTS ---

const TimeInput = ({ 
  value, 
  onChange,
  className 
}: { 
  value: number, 
  onChange: (val: number) => void,
  className?: string 
}) => {
  const [localValue, setLocalValue] = useState(secondsToMMSS(value));
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    if (!isEditing) {
      setLocalValue(secondsToMMSS(value));
    }
  }, [value, isEditing]);

  const handleBlur = () => {
    setIsEditing(false);
    const seconds = mmssToSeconds(localValue);
    onChange(seconds);
    setLocalValue(secondsToMMSS(seconds));
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
  };

  return (
    <input
      type="text"
      className={className}
      value={localValue}
      onChange={(e) => setLocalValue(e.target.value)}
      onFocus={() => setIsEditing(true)}
      onBlur={handleBlur}
      onKeyDown={handleKeyDown}
      placeholder="00:00.00"
    />
  );
};

const DebouncedTextArea = ({ 
    value, 
    onChange, 
    onBlur, 
    className, 
    rows,
    placeholder
}: { 
    value: string, 
    onChange: (val: string) => void, 
    onBlur: () => void,
    className?: string,
    rows?: number,
    placeholder?: string
}) => {
    const [localValue, setLocalValue] = useState(value);
    const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => { setLocalValue(value); }, [value]);

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const newValue = e.target.value;
        setLocalValue(newValue);
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        timeoutRef.current = setTimeout(() => onChange(newValue), 300);
    };

    return (
        <textarea
            className={className}
            rows={rows}
            value={localValue}
            onChange={handleChange}
            onBlur={onBlur}
            placeholder={placeholder}
        />
    );
};

const EffectToggle: React.FC<{ label: string, isActive: boolean | undefined, onToggle: () => void }> = ({ label, isActive, onToggle }) => {
    return (
        <button
            onClick={onToggle}
            className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                isActive === true 
                ? 'bg-purple-600 border-purple-400 text-white font-bold shadow-[0_0_10px_rgba(147,51,234,0.3)]' 
                : isActive === false 
                ? 'bg-red-900/50 border-red-500/30 text-red-300 line-through decoration-red-500' // Forced Off
                : 'bg-neutral-800 border-white/5 text-gray-500 hover:border-white/20' // Global
            }`}
        >
            {label}
        </button>
    );
};

// New Component: Visual Timeline Track
const VisualTimelineTrack: React.FC<{ 
    duration: number, 
    items: Array<{type: string, data: any}>, 
    currentTime: number, 
    onSeek: (t: number) => void 
}> = ({ duration, items, currentTime, onSeek }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const maxDur = Math.max(duration, 10); // Minimum 10s timeline

    const handleClick = (e: React.MouseEvent) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const percent = Math.max(0, Math.min(1, x / rect.width));
        onSeek(percent * maxDur);
    };

    return (
        <div className="w-full bg-neutral-900 h-16 border-b border-white/5 relative select-none overflow-hidden group cursor-crosshair" onClick={handleClick} ref={containerRef}>
            {/* Grid Lines */}
            <div className="absolute inset-0 flex" style={{ opacity: 0.1 }}>
                {Array.from({ length: 10 }).map((_, i) => (
                    <div key={i} className="flex-1 border-r border-white"></div>
                ))}
            </div>

            {/* Blocks */}
            {items.map((item, i) => {
                const { start, end } = item.data;
                const left = (start / maxDur) * 100;
                const width = Math.max(0.2, ((end - start) / maxDur) * 100);
                const isLyric = item.type === 'segment';

                return (
                    <div 
                        key={i}
                        className={`absolute top-0 bottom-0 border-r border-black/20 ${isLyric ? 'bg-cyan-500/20 hover:bg-cyan-500/40 border-t-2 border-t-cyan-500/50' : 'bg-purple-500/20 hover:bg-purple-500/40 border-b-2 border-b-purple-500/50 h-3/4 top-auto'}`}
                        style={{ left: `${left}%`, width: `${width}%` }}
                        title={isLyric ? item.data.text : item.data.label}
                    />
                );
            })}

            {/* Playhead */}
            <div 
                className="absolute top-0 bottom-0 w-0.5 bg-red-500 shadow-[0_0_10px_red] z-10 pointer-events-none transition-all duration-75 ease-linear"
                style={{ left: `${(currentTime / maxDur) * 100}%` }}
            >
                <div className="absolute -top-1 -left-1.5 w-4 h-4 bg-red-500 rotate-45 transform -translate-y-1/2" />
            </div>

            {/* Time Indicator */}
            <div className="absolute bottom-1 right-2 text-[9px] font-mono text-gray-500 bg-black/50 px-1 rounded">
                {secondsToMMSS(maxDur)}
            </div>
        </div>
    );
};

// --- MAIN COMPONENT ---

export const TimelineEditor: React.FC<TimelineEditorProps> = ({ 
    data, 
    onUpdate, 
    currentTime, 
    onSeek,
    eventBlocks,
    onUpdateEventBlocks,
    customEffects = [],
    projectConfig,
    duration = 60
}) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [activeTabMap, setActiveTabMap] = useState<Record<string, 'text' | 'style'>>({});
  const [autoScroll, setAutoScroll] = useState(true);

  const setTab = (id: string, tab: 'text' | 'style') => {
      setActiveTabMap(prev => ({...prev, [id]: tab}));
  };

  // --- DATA UPDATERS ---

  const updateSegmentData = (index: number, updates: Partial<Segment>, shouldRecalculateWords = false) => {
    const newSegments = [...data.segments];
    const oldSegment = newSegments[index];
    let updatedSegment = { ...oldSegment, ...updates };

    if (shouldRecalculateWords) {
         updatedSegment.words = recalculateWords(updatedSegment.text, updatedSegment.start, updatedSegment.end);
    } else if (updates.start !== undefined || updates.end !== undefined) {
         const oldDuration = oldSegment.end - oldSegment.start;
         const newDuration = updatedSegment.end - updatedSegment.start;
         if (oldDuration > 0 && updatedSegment.words.length > 0) {
             const ratio = newDuration / oldDuration;
             updatedSegment.words = oldSegment.words.map(w => ({
                 ...w,
                 start: updatedSegment.start + (w.start - oldSegment.start) * ratio,
                 end: updatedSegment.start + (w.end - oldSegment.start) * ratio
             }));
         } else {
             updatedSegment.words = recalculateWords(updatedSegment.text, updatedSegment.start, updatedSegment.end);
         }
    }
    newSegments[index] = updatedSegment;
    if (updates.start !== undefined) newSegments.sort((a, b) => a.start - b.start);
    onUpdate({ ...data, segments: newSegments });
  };

  const updateSegmentStyle = (index: number, styleUpdates: Partial<Segment['style']>) => {
      const newSegments = [...data.segments];
      const segment = newSegments[index];
      const currentStyle = segment.style || {};

      // Clean up undefined/empty values
      const newStyle = { ...currentStyle, ...styleUpdates };
      Object.keys(newStyle).forEach(key => {
          // @ts-ignore
          if (newStyle[key] === undefined || newStyle[key] === '') delete newStyle[key];
      });

      newSegments[index] = { ...segment, style: newStyle };
      onUpdate({ ...data, segments: newSegments });
  };

  const handleDeleteSegment = (index: number) => {
    if(!confirm("Delete this lyric segment?")) return;
    const newSegments = [...data.segments];
    newSegments.splice(index, 1);
    onUpdate({ ...data, segments: newSegments });
  };

  const handleAddSegment = () => {
    const newSegments = [...data.segments];
    const lastSeg = newSegments[newSegments.length - 1];
    const newStart = lastSeg ? lastSeg.end + 0.2 : 0;
    const newSegment: Segment = {
        id: Date.now().toString(),
        start: newStart,
        end: newStart + 2.0,
        text: "New Line",
        section: undefined, 
        words: []
    };
    newSegment.words = recalculateWords(newSegment.text, newSegment.start, newSegment.end);
    newSegments.push(newSegment);
    onUpdate({ ...data, segments: newSegments });
  };

  // --- EVENT BLOCK UPDATERS ---

  const handleAddEventBlock = () => {
      const newBlock: EventBlock = {
          id: `evt-${Date.now()}`,
          start: currentTime,
          end: currentTime + 5,
          label: "FX Block",
          overrides: {},
          collapsed: false,
          smoothIn: false,
          smoothOut: false
      };
      onUpdateEventBlocks([...eventBlocks, newBlock].sort((a, b) => a.start - b.start));
  };

  const updateEventBlock = (id: string, updates: Partial<EventBlock>) => {
      let newBlocks = eventBlocks.map(b => b.id === id ? { ...b, ...updates } : b);
      if (updates.start !== undefined) newBlocks.sort((a, b) => a.start - b.start);
      onUpdateEventBlocks(newBlocks);
  };

  const toggleOverride = (blockId: string, key: keyof EffectOverrides) => {
      const block = eventBlocks.find(b => b.id === blockId);
      if(!block) return;

      const current = block.overrides[key];
      // Cycle: undefined (Global) -> true (On) -> false (Off) -> undefined
      let next: boolean | undefined;
      if (current === undefined) next = true;
      else if (current === true) next = false;
      else next = undefined;

      const newOverrides = { ...block.overrides, [key]: next };
      // Remove key if undefined to clean up
      if (next === undefined) delete newOverrides[key];

      updateEventBlock(blockId, { overrides: newOverrides });
  };

  const toggleCustomOverride = (blockId: string, effectId: string) => {
      const block = eventBlocks.find(b => b.id === blockId);
      if(!block) return;

      const currentMap = block.overrides.custom_fx || {};
      const current = currentMap[effectId];

      let next: boolean | undefined;
      if (current === undefined) next = true;
      else if (current === true) next = false;
      else next = undefined;

      const newMap = { ...currentMap, [effectId]: next };
      if (next === undefined) delete newMap[effectId];

      const newOverrides = { ...block.overrides };
      if (Object.keys(newMap).length === 0) {
          delete newOverrides.custom_fx;
      } else {
          // @ts-ignore 
          newOverrides.custom_fx = newMap;
      }

      updateEventBlock(blockId, { overrides: newOverrides });
  };

  const deleteEventBlock = (id: string) => {
      if(!confirm("Delete this event block?")) return;
      onUpdateEventBlocks(eventBlocks.filter(b => b.id !== id));
  };

  // --- RENDER HELPERS ---

  // Combine and sort lyrics and events for display
  const combinedItems = [
      ...data.segments.map((s, i) => ({ type: 'segment' as const, data: s, index: i, start: s.start })),
      ...eventBlocks.map((b, i) => ({ type: 'block' as const, data: b, index: i, start: b.start }))
  ].sort((a, b) => a.start - b.start);

  const SECTION_COLORS: Record<string, string> = {
      verse: 'border-blue-500',
      chorus: 'border-pink-500',
      bridge: 'border-yellow-500',
      intro: 'border-gray-500',
      outro: 'border-red-500'
  };

  const SECTION_BG: Record<string, string> = {
      verse: 'bg-blue-950/40 text-blue-200',
      chorus: 'bg-pink-950/40 text-pink-200',
      bridge: 'bg-yellow-950/40 text-yellow-200',
      intro: 'bg-gray-800/60 text-gray-300',
      outro: 'bg-red-950/40 text-red-200'
  };

  const getSectionColor = (name: string) => SECTION_COLORS[name.toLowerCase().split(' ')[0]] || 'border-gray-600';
  const getSectionBg = (name: string) => SECTION_BG[name.toLowerCase().split(' ')[0]] || 'bg-neutral-800 text-gray-400';

  let currentSection = 'verse'; 

  // Auto-scroll logic
  useEffect(() => {
    if (!autoScroll) return;

    const activeItem = combinedItems.find(item => {
        if(item.type === 'segment') return currentTime >= item.data.start && currentTime <= item.data.end;
        if(item.type === 'block') return currentTime >= item.data.start && currentTime <= item.data.end;
        return false;
    });

    if (activeItem && scrollRef.current) {
        const id = activeItem.type === 'segment' ? activeItem.data.id : activeItem.data.id;
        const row = scrollRef.current.querySelector(`[data-id="${id}"]`) as HTMLElement;
        if (row) {
            const container = scrollRef.current;
            const rowTop = row.offsetTop;
            const rowBottom = rowTop + row.offsetHeight;
            const containerTop = container.scrollTop;
            const containerBottom = containerTop + container.offsetHeight;
            if (rowTop < containerTop || rowBottom > containerBottom) {
                 row.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
  }, [currentTime]); // Removed combinedItems from dependencies to prevent jump on edit

  return (
    <div className="flex flex-col h-full bg-neutral-900 border-l border-white/5">

        {/* VISUAL TRACK */}
        <VisualTimelineTrack 
            duration={duration} 
            items={combinedItems} 
            currentTime={currentTime} 
            onSeek={onSeek} 
        />

        {/* HEADER TOOLBAR */}
        <div className="p-3 border-b border-white/5 flex justify-between items-center bg-neutral-800 shrink-0">
            <div className="flex items-center gap-2">
                <Clock size={16} className="text-cyan-400" /> 
                <span className="text-xs font-bold text-gray-200 uppercase tracking-widest">Detail View</span>
                <button 
                    onClick={() => setAutoScroll(!autoScroll)}
                    className={`ml-2 p-1 rounded-full transition-colors ${autoScroll ? 'bg-cyan-500/20 text-cyan-400' : 'bg-transparent text-gray-600 hover:text-gray-400'}`}
                    title={autoScroll ? "Disable Auto-Scroll" : "Enable Auto-Scroll"}
                >
                    <ArrowDownCircle size={14} />
                </button>
            </div>

            <div className="flex gap-2">
                <button 
                    onClick={handleAddEventBlock}
                    className="text-[10px] flex items-center gap-1 bg-purple-900/50 hover:bg-purple-800/80 border border-purple-500/50 px-3 py-1.5 rounded text-purple-200 transition-colors font-bold"
                >
                    <Zap size={12} /> Event
                </button>
                <button 
                    onClick={handleAddSegment}
                    className="text-[10px] flex items-center gap-1 bg-cyan-900/50 hover:bg-cyan-800/80 border border-cyan-500/50 px-3 py-1.5 rounded text-cyan-200 transition-colors font-bold"
                >
                    <Plus size={12} /> Line
                </button>
            </div>
        </div>

        {/* LIST AREA */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-3" ref={scrollRef}>
            {combinedItems.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-40 text-gray-500 border-2 border-dashed border-white/5 rounded-xl">
                    <AlertCircle className="mb-2 opacity-50" />
                    <span className="text-xs">Timeline Empty</span>
                    <span className="text-xs text-gray-600 mt-1">Add a Lyric Line or FX Event</span>
                </div>
            ) : (
                combinedItems.map((item) => {
                    // --- RENDER LYRIC SEGMENT ---
                    if (item.type === 'segment') {
                        const seg = item.data;
                        const idx = item.index;
                        const isActive = currentTime >= seg.start && currentTime <= seg.end;
                        const currentTab = activeTabMap[seg.id] || 'text';

                        // Handle Section Headers
                        const isNewSection = !!seg.section;
                        if (isNewSection) currentSection = seg.section!;
                        else if (idx === 0 && !seg.section) currentSection = 'verse'; 

                        return (
                             <div key={seg.id} className="flex flex-col gap-1">
                                {isNewSection && (
                                    <div className={`flex items-center justify-between px-3 py-1.5 rounded-md mt-2 ${getSectionBg(currentSection)} border border-white/5 shadow-sm sticky top-0 z-10`}>
                                        <div className="flex items-center gap-2">
                                            <Tag size={12} className="opacity-70" />
                                            <span className="text-[10px] font-bold uppercase tracking-widest">{currentSection}</span>
                                        </div>
                                    </div>
                                )}
                                <div 
                                    data-id={seg.id}
                                    className={`group relative flex flex-col rounded-lg border border-white/5 transition-all duration-200 overflow-hidden ${
                                        isActive ? 'bg-cyan-950/20 border-cyan-500/30' : 'bg-neutral-800/80 hover:border-white/20'
                                    }`}
                                >
                                    {/* Vertical Color Indicator */}
                                    <div className={`absolute left-0 top-0 bottom-0 w-1 ${getSectionColor(currentSection).replace('border-','bg-')}`}></div>

                                    {/* Card Toolbar */}
                                    <div className="flex items-center justify-between p-2 pl-3 bg-black/20 border-b border-white/5">
                                        {/* Tabs */}
                                        <div className="flex gap-1 bg-black/40 p-0.5 rounded-md">
                                            <button 
                                                onClick={() => setTab(seg.id, 'text')}
                                                className={`p-1 rounded text-[10px] flex items-center gap-1 ${currentTab === 'text' ? 'bg-neutral-700 text-white shadow-sm' : 'text-gray-500 hover:text-gray-300'}`}
                                            >
                                                <Type size={12} /> Text
                                            </button>
                                            <button 
                                                onClick={() => setTab(seg.id, 'style')}
                                                className={`p-1 rounded text-[10px] flex items-center gap-1 ${currentTab === 'style' ? 'bg-neutral-700 text-white shadow-sm' : 'text-gray-500 hover:text-gray-300'}`}
                                            >
                                                <Palette size={12} /> Style
                                            </button>
                                        </div>

                                        {/* Actions */}
                                        <div className="flex items-center gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                                             {!isNewSection && (
                                                <button onClick={() => updateSegmentData(idx, { section: 'new section' })} className="p-1 rounded-md hover:bg-white/10 text-gray-400 hover:text-white" title="Start New Section">
                                                    <FolderInput size={14} />
                                                </button>
                                             )}
                                             <button onClick={() => onSeek(seg.start)} className={`p-1 rounded-md transition-colors ${isActive ? 'text-cyan-400' : 'hover:bg-white/10 text-gray-400'}`}>
                                                 <PlayCircle size={14} fill={isActive ? "currentColor" : "none"} />
                                             </button>
                                             <button onClick={() => handleDeleteSegment(idx)} className="p-1 rounded-md hover:bg-red-500/20 text-gray-500 hover:text-red-400">
                                                 <Trash2 size={14} />
                                             </button>
                                        </div>
                                    </div>

                                    {/* TAB CONTENT: TEXT */}
                                    {currentTab === 'text' && (
                                        <div className="p-3">
                                            <div className="flex items-center justify-between gap-3 mb-2">
                                                <div className="flex items-center gap-1">
                                                    <TimeInput className="bg-neutral-900 border border-white/10 rounded px-1 w-14 text-[10px] font-mono text-gray-300 outline-none focus:border-cyan-500" value={seg.start} onChange={(val) => updateSegmentData(idx, { start: val })} />
                                                    <span className="text-gray-600 text-[10px]">to</span>
                                                    <TimeInput className="bg-neutral-900 border border-white/10 rounded px-1 w-14 text-[10px] font-mono text-gray-300 outline-none focus:border-cyan-500" value={seg.end} onChange={(val) => updateSegmentData(idx, { end: val })} />
                                                </div>
                                            </div>
                                            <DebouncedTextArea
                                                className={`w-full bg-transparent text-sm outline-none resize-none font-medium leading-relaxed transition-colors placeholder-gray-700 ${isActive ? 'text-white' : 'text-gray-300'}`}
                                                rows={Math.max(1, seg.text.split('\n').length)}
                                                value={seg.text}
                                                onChange={(val) => updateSegmentData(idx, { text: val }, true)} 
                                                onBlur={() => {}} 
                                                placeholder="Enter lyrics..."
                                            />
                                        </div>
                                    )}

                                    {/* TAB CONTENT: STYLE */}
                                    {currentTab === 'style' && (
                                        <div className="p-3 bg-neutral-900/50">
                                            <div className="grid grid-cols-2 gap-3 mb-3">
                                                <div className="space-y-1">
                                                    <label className="text-[9px] text-gray-500 uppercase font-bold">Text Color</label>
                                                    <div className="flex gap-2 items-center">
                                                        <input 
                                                            type="color" 
                                                            value={seg.style?.colorText || projectConfig?.colors.text || '#ffffff'} 
                                                            onChange={(e) => updateSegmentStyle(idx, { colorText: e.target.value })}
                                                            className="w-6 h-6 bg-transparent cursor-pointer rounded overflow-hidden"
                                                        />
                                                        {projectConfig && (
                                                            <div className="flex gap-1">
                                                                {[projectConfig.colors.text, projectConfig.colors.active, projectConfig.colors.secondary].map(c => (
                                                                    <div key={c} onClick={() => updateSegmentStyle(idx, { colorText: c })} className="w-4 h-4 rounded-full cursor-pointer border border-white/10 hover:scale-110 transition-transform" style={{background: c}}></div>
                                                                ))}
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                                <div className="space-y-1">
                                                    <label className="text-[9px] text-gray-500 uppercase font-bold">Active Glow</label>
                                                    <div className="flex gap-2 items-center">
                                                        <input 
                                                            type="color" 
                                                            value={seg.style?.colorActive || projectConfig?.colors.active || '#00ffff'} 
                                                            onChange={(e) => updateSegmentStyle(idx, { colorActive: e.target.value })}
                                                            className="w-6 h-6 bg-transparent cursor-pointer rounded overflow-hidden"
                                                        />
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="space-y-1">
                                                <div className="flex justify-between">
                                                    <label className="text-[9px] text-gray-500 uppercase font-bold">Font Scale</label>
                                                    <span className="text-[9px] text-gray-400">{seg.style?.scale || 1.0}x</span>
                                                </div>
                                                <input 
                                                    type="range" min="0.5" max="3.0" step="0.1"
                                                    value={seg.style?.scale || 1.0}
                                                    onChange={(e) => updateSegmentStyle(idx, { scale: parseFloat(e.target.value) })}
                                                    className="w-full h-1 bg-neutral-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                                                />
                                            </div>

                                            <div className="mt-3 flex justify-end">
                                                <button onClick={() => updateSegmentStyle(idx, { colorText: undefined, colorActive: undefined, scale: 1.0 })} className="text-[9px] text-red-400 hover:text-red-300">
                                                    Reset Styles
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                             </div>
                        );
                    } 

                    // --- RENDER EVENT BLOCK ---
                    else {
                        const block = item.data;
                        const isActive = currentTime >= block.start && currentTime <= block.end;

                        return (
                            <div 
                                key={block.id}
                                data-id={block.id}
                                className={`group relative p-3 rounded-lg border border-purple-500/30 transition-all ${
                                    isActive ? 'bg-purple-950/40 shadow-[0_0_15px_rgba(147,51,234,0.1)]' : 'bg-neutral-900/80 hover:bg-neutral-800'
                                }`}
                            >
                                <div className="absolute left-0 top-0 bottom-0 w-1 bg-purple-500 rounded-l-lg"></div>

                                {/* HEADER */}
                                <div className="flex items-center justify-between mb-2 pl-2">
                                     <div className="flex items-center gap-2">
                                         <Zap size={14} className="text-purple-400" />
                                         <input 
                                            value={block.label}
                                            onChange={(e) => updateEventBlock(block.id, { label: e.target.value })}
                                            className="bg-transparent text-xs font-bold text-purple-200 outline-none w-32 border-b border-transparent hover:border-purple-500/50 focus:border-purple-500"
                                         />

                                         {/* FADE CONTROLS */}
                                         <div className="flex items-center gap-1 ml-2 border-l border-white/10 pl-2">
                                             <button 
                                                onClick={() => updateEventBlock(block.id, { smoothIn: !block.smoothIn })}
                                                className={`p-1 rounded ${block.smoothIn ? 'text-green-400 bg-green-950/30' : 'text-gray-600 hover:text-gray-400'}`}
                                                title="Fade In"
                                             >
                                                 <TrendingUp size={12} />
                                             </button>
                                             <button 
                                                onClick={() => updateEventBlock(block.id, { smoothOut: !block.smoothOut })}
                                                className={`p-1 rounded ${block.smoothOut ? 'text-green-400 bg-green-950/30' : 'text-gray-600 hover:text-gray-400'}`}
                                                title="Fade Out"
                                             >
                                                 <TrendingDown size={12} />
                                             </button>
                                         </div>
                                     </div>
                                     <div className="flex items-center gap-2">
                                          <div className="flex items-center gap-1 bg-black/40 rounded px-1.5 py-0.5 border border-white/5">
                                              <TimeInput className="bg-transparent w-12 text-[10px] font-mono text-gray-400 outline-none text-right" value={block.start} onChange={(v) => updateEventBlock(block.id, { start: v })} />
                                              <span className="text-[10px] text-gray-600">-</span>
                                              <TimeInput className="bg-transparent w-12 text-[10px] font-mono text-gray-400 outline-none text-right" value={block.end} onChange={(v) => updateEventBlock(block.id, { end: v })} />
                                          </div>
                                          <button onClick={() => updateEventBlock(block.id, { collapsed: !block.collapsed })} className="p-1 hover:text-white text-gray-500">
                                              {block.collapsed ? <ChevronDown size={14} /> : <ChevronUp size={14} />}
                                          </button>

                                          {/* DELETE BUTTON */}
                                          <button 
                                            onClick={() => deleteEventBlock(block.id)} 
                                            className="p-1.5 bg-red-950/20 hover:bg-red-900/50 rounded text-red-700 hover:text-red-400 border border-red-900/10 hover:border-red-900/50 ml-1"
                                            title="Delete FX Block"
                                          >
                                              <Trash2 size={12} />
                                          </button>
                                     </div>
                                </div>

                                {/* ACTIVE OVERRIDES INDICATOR (Collapsed Mode) */}
                                {block.collapsed && (
                                    <div className="flex flex-wrap gap-1 pl-2">
                                        {Object.entries(block.overrides).map(([k, v]) => {
                                            if (k === 'custom_fx') return null; // Handle separately or ignore in summary
                                            return (
                                                <span key={k} className="text-[9px] bg-purple-900/50 text-purple-300 px-1.5 py-0.5 rounded border border-purple-500/20">
                                                    {k.replace('fx_', '').replace('cam_', '')}
                                                </span>
                                            )
                                        })}
                                        {block.overrides.custom_fx && Object.keys(block.overrides.custom_fx).length > 0 && (
                                            <span className="text-[9px] bg-cyan-900/50 text-cyan-300 px-1.5 py-0.5 rounded border border-cyan-500/20">
                                                +{Object.keys(block.overrides.custom_fx).length} Custom
                                            </span>
                                        )}
                                    </div>
                                )}

                                {/* FULL EDITOR (Expanded Mode) */}
                                {!block.collapsed && (
                                    <div className="pl-2 grid grid-cols-2 gap-4 mt-3 pt-3 border-t border-white/5">
                                         {/* VFX */}
                                         <div>
                                             <h4 className="text-[9px] font-bold text-gray-500 uppercase mb-2">Visual FX</h4>
                                             <div className="flex flex-wrap gap-2">
                                                 <EffectToggle label="Glitch" isActive={block.overrides.fx_chromaticAberration} onToggle={() => toggleOverride(block.id, 'fx_chromaticAberration')} />
                                                 <EffectToggle label="VHS" isActive={block.overrides.fx_vhs} onToggle={() => toggleOverride(block.id, 'fx_vhs')} />
                                                 <EffectToggle label="Pixelate" isActive={block.overrides.fx_mosaic} onToggle={() => toggleOverride(block.id, 'fx_mosaic')} />
                                                 <EffectToggle label="Invert" isActive={block.overrides.fx_invert} onToggle={() => toggleOverride(block.id, 'fx_invert')} />
                                                 <EffectToggle label="Mirror" isActive={block.overrides.fx_mirror} onToggle={() => toggleOverride(block.id, 'fx_mirror')} />
                                                 <EffectToggle label="RGB Split" isActive={block.overrides.fx_rgbSplit} onToggle={() => toggleOverride(block.id, 'fx_rgbSplit')} />
                                                 <EffectToggle label="Scanlines" isActive={block.overrides.fx_scanlines} onToggle={() => toggleOverride(block.id, 'fx_scanlines')} />
                                                 <EffectToggle label="Kaleidoscope" isActive={block.overrides.fx_kaleidoscope} onToggle={() => toggleOverride(block.id, 'fx_kaleidoscope')} />
                                                 <EffectToggle label="Halftone" isActive={block.overrides.fx_halftone} onToggle={() => toggleOverride(block.id, 'fx_halftone')} />
                                                 <EffectToggle label="Old Movie" isActive={block.overrides.fx_oldMovie} onToggle={() => toggleOverride(block.id, 'fx_oldMovie')} />
                                             </div>
                                         </div>
                                         {/* Camera */}
                                         <div>
                                             <h4 className="text-[9px] font-bold text-gray-500 uppercase mb-2">Camera</h4>
                                             <div className="flex flex-wrap gap-2">
                                                 <EffectToggle label="Shake" isActive={block.overrides.cam_shake} onToggle={() => toggleOverride(block.id, 'cam_shake')} />
                                                 <EffectToggle label="Zoom Beat" isActive={block.overrides.cam_zoomBeat} onToggle={() => toggleOverride(block.id, 'cam_zoomBeat')} />
                                                 <EffectToggle label="Hard Kick" isActive={block.overrides.cam_hardKick} onToggle={() => toggleOverride(block.id, 'cam_hardKick')} />
                                                 <EffectToggle label="Panic" isActive={block.overrides.cam_panic} onToggle={() => toggleOverride(block.id, 'cam_panic')} />
                                                 <EffectToggle label="Sway" isActive={block.overrides.cam_sway} onToggle={() => toggleOverride(block.id, 'cam_sway')} />
                                                 <EffectToggle label="Rotate" isActive={block.overrides.cam_rotate} onToggle={() => toggleOverride(block.id, 'cam_rotate')} />
                                             </div>
                                             <h4 className="text-[9px] font-bold text-gray-500 uppercase mb-2 mt-3">Particles</h4>
                                             <EffectToggle label="Particles" isActive={block.overrides.part_enabled} onToggle={() => toggleOverride(block.id, 'part_enabled')} />
                                         </div>

                                         {/* Custom Effects */}
                                         {customEffects && customEffects.length > 0 && (
                                             <div className="col-span-2 pt-3 mt-3 border-t border-white/5">
                                                 <h4 className="text-[9px] font-bold text-cyan-500 uppercase mb-2">Custom Effects</h4>
                                                 <div className="flex flex-wrap gap-2">
                                                     {customEffects.map(fx => (
                                                         <EffectToggle 
                                                            key={fx.id} 
                                                            label={fx.name} 
                                                            isActive={block.overrides.custom_fx?.[fx.id]} 
                                                            onToggle={() => toggleCustomOverride(block.id, fx.id)} 
                                                         />
                                                     ))}
                                                 </div>
                                             </div>
                                         )}
                                    </div>
                                )}
                            </div>
                        );
                    }
                })
            )}

            <div className="h-20"></div>
        </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { LyricData, Segment, Word, EventBlock, EffectOverrides, CustomEffect, RendererConfig } from '../types';
import { Clock, Trash2, Plus, PlayCircle, Download, AlertCircle, ChevronDown, ChevronUp, Tag, X, FolderInput, Check, Zap, Eye, EyeOff, TrendingUp, TrendingDown, Palette, Type, MousePointer2, ArrowDownCircle } from 'lucide-react';

interface TimelineEditorProps {
  data: LyricData;
  onUpdate: (data: LyricData) => void;
  currentTime: number;
  onSeek: (time: number) => void;
  eventBlocks: EventBlock[];
  onUpdateEventBlocks: (blocks: EventBlock[]) => void;
  customEffects?: CustomEffect[]; 
  projectConfig?: RendererConfig; // Need access to project colors for the palette
  duration?: number;
}

// --- HELPER FUNCTIONS ---

const secondsToMMSS = (seconds: number): string => {
  const m = Math.floor(seconds / 60);
  const s = (seconds % 60).toFixed(2);
  const sStr = s.includes('.') ? s : `${s}.00`;
  return `${m.toString().padStart(2, '0')}:${sStr.padStart(5, '0')}`;
};

const mmssToSeconds = (timeStr: string): number => {
  const parts = timeStr.split(':');
  if (parts.length === 2) {
    const minutes = parseInt(parts[0], 10);
    const seconds = parseFloat(parts[1]);
    return (minutes * 60) + seconds;
  }
  return parseFloat(timeStr) || 0;
};

// Recalculates word timings linearly across the segment duration
const recalculateWords = (text: string, start: number, end: number): Word[] => {
  const lines = text.split('\n');
  const words: Word[] = [];
  const duration = Math.max(0.1, end - start);

  let totalWordCount = 0;
  lines.forEach(line => {
    totalWordCount += line.trim().split(/\s+/).filter(w => w.length > 0).length;
  });

  if (totalWordCount === 0) return [];

  const timePerWord = duration / totalWordCount;
  let currentWordIndex = 0;

  lines.forEach((line, lineIdx) => {
    const lineWords = line.trim().split(/\s+/).filter(w => w.length > 0);
    lineWords.forEach((w) => {
      const wordStart = start + (currentWordIndex * timePerWord);
      const wordEnd = wordStart + timePerWord;
      words.push({
        word: w,
        start: wordStart,
        end: wordEnd,
        probability: 1,
        line_number: lineIdx
      });
      currentWordIndex++;
    });
  });

  return words;
};

// --- SUB-COMPONENTS ---

const TimeInput = ({ 
  value, 
  onChange,
  className 
}: { 
  value: number, 
  onChange: (val: number) => void,
  className?: string 
}) => {
  const [localValue, setLocalValue] = useState(secondsToMMSS(value));
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    if (!isEditing) {
      setLocalValue(secondsToMMSS(value));
    }
  }, [value, isEditing]);

  const handleBlur = () => {
    setIsEditing(false);
    const seconds = mmssToSeconds(localValue);
    onChange(seconds);
    setLocalValue(secondsToMMSS(seconds));
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
  };

  return (
    <input
      type="text"
      className={className}
      value={localValue}
      onChange={(e) => setLocalValue(e.target.value)}
      onFocus={() => setIsEditing(true)}
      onBlur={handleBlur}
      onKeyDown={handleKeyDown}
      placeholder="00:00.00"
    />
  );
};

const DebouncedTextArea = ({ 
    value, 
    onChange, 
    onBlur, 
    className, 
    rows,
    placeholder
}: { 
    value: string, 
    onChange: (val: string) => void, 
    onBlur: () => void,
    className?: string,
    rows?: number,
    placeholder?: string
}) => {
    const [localValue, setLocalValue] = useState(value);
    const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => { setLocalValue(value); }, [value]);

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const newValue = e.target.value;
        setLocalValue(newValue);
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        timeoutRef.current = setTimeout(() => onChange(newValue), 300);
    };

    return (
        <textarea
            className={className}
            rows={rows}
            value={localValue}
            onChange={handleChange}
            onBlur={onBlur}
            placeholder={placeholder}
        />
    );
};

const EffectToggle: React.FC<{ label: string, isActive: boolean | undefined, onToggle: () => void }> = ({ label, isActive, onToggle }) => {
    return (
        <button
            onClick={onToggle}
            className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                isActive === true 
                ? 'bg-purple-600 border-purple-400 text-white font-bold shadow-[0_0_10px_rgba(147,51,234,0.3)]' 
                : isActive === false 
                ? 'bg-red-900/50 border-red-500/30 text-red-300 line-through decoration-red-500' // Forced Off
                : 'bg-neutral-800 border-white/5 text-gray-500 hover:border-white/20' // Global
            }`}
        >
            {label}
        </button>
    );
};

// New Component: Visual Timeline Track
const VisualTimelineTrack: React.FC<{ 
    duration: number, 
    items: Array<{type: string, data: any}>, 
    currentTime: number, 
    onSeek: (t: number) => void 
}> = ({ duration, items, currentTime, onSeek }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const maxDur = Math.max(duration, 10); // Minimum 10s timeline

    const handleClick = (e: React.MouseEvent) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const percent = Math.max(0, Math.min(1, x / rect.width));
        onSeek(percent * maxDur);
    };

    return (
        <div className="w-full bg-neutral-900 h-16 border-b border-white/5 relative select-none overflow-hidden group cursor-crosshair" onClick={handleClick} ref={containerRef}>
            {/* Grid Lines */}
            <div className="absolute inset-0 flex" style={{ opacity: 0.1 }}>
                {Array.from({ length: 10 }).map((_, i) => (
                    <div key={i} className="flex-1 border-r border-white"></div>
                ))}
            </div>

            {/* Blocks */}
            {items.map((item, i) => {
                const { start, end } = item.data;
                const left = (start / maxDur) * 100;
                const width = Math.max(0.2, ((end - start) / maxDur) * 100);
                const isLyric = item.type === 'segment';

                return (
                    <div 
                        key={i}
                        className={`absolute top-0 bottom-0 border-r border-black/20 ${isLyric ? 'bg-cyan-500/20 hover:bg-cyan-500/40 border-t-2 border-t-cyan-500/50' : 'bg-purple-500/20 hover:bg-purple-500/40 border-b-2 border-b-purple-500/50 h-3/4 top-auto'}`}
                        style={{ left: `${left}%`, width: `${width}%` }}
                        title={isLyric ? item.data.text : item.data.label}
                    />
                );
            })}

            {/* Playhead */}
            <div 
                className="absolute top-0 bottom-0 w-0.5 bg-red-500 shadow-[0_0_10px_red] z-10 pointer-events-none transition-all duration-75 ease-linear"
                style={{ left: `${(currentTime / maxDur) * 100}%` }}
            >
                <div className="absolute -top-1 -left-1.5 w-4 h-4 bg-red-500 rotate-45 transform -translate-y-1/2" />
            </div>

            {/* Time Indicator */}
            <div className="absolute bottom-1 right-2 text-[9px] font-mono text-gray-500 bg-black/50 px-1 rounded">
                {secondsToMMSS(maxDur)}
            </div>
        </div>
    );
};

// --- MAIN COMPONENT ---

export const TimelineEditor: React.FC<TimelineEditorProps> = ({ 
    data, 
    onUpdate, 
    currentTime, 
    onSeek,
    eventBlocks,
    onUpdateEventBlocks,
    customEffects = [],
    projectConfig,
    duration = 60
}) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [activeTabMap, setActiveTabMap] = useState<Record<string, 'text' | 'style'>>({});
  const [autoScroll, setAutoScroll] = useState(true);

  const setTab = (id: string, tab: 'text' | 'style') => {
      setActiveTabMap(prev => ({...prev, [id]: tab}));
  };

  // --- DATA UPDATERS ---

  const updateSegmentData = (index: number, updates: Partial<Segment>, shouldRecalculateWords = false) => {
    const newSegments = [...data.segments];
    const oldSegment = newSegments[index];
    let updatedSegment = { ...oldSegment, ...updates };

    if (shouldRecalculateWords) {
         updatedSegment.words = recalculateWords(updatedSegment.text, updatedSegment.start, updatedSegment.end);
    } else if (updates.start !== undefined || updates.end !== undefined) {
         const oldDuration = oldSegment.end - oldSegment.start;
         const newDuration = updatedSegment.end - updatedSegment.start;
         if (oldDuration > 0 && updatedSegment.words.length > 0) {
             const ratio = newDuration / oldDuration;
             updatedSegment.words = oldSegment.words.map(w => ({
                 ...w,
                 start: updatedSegment.start + (w.start - oldSegment.start) * ratio,
                 end: updatedSegment.start + (w.end - oldSegment.start) * ratio
             }));
         } else {
             updatedSegment.words = recalculateWords(updatedSegment.text, updatedSegment.start, updatedSegment.end);
         }
    }
    newSegments[index] = updatedSegment;
    if (updates.start !== undefined) newSegments.sort((a, b) => a.start - b.start);
    onUpdate({ ...data, segments: newSegments });
  };

  const updateSegmentStyle = (index: number, styleUpdates: Partial<Segment['style']>) => {
      const newSegments = [...data.segments];
      const segment = newSegments[index];
      const currentStyle = segment.style || {};

      // Clean up undefined/empty values
      const newStyle = { ...currentStyle, ...styleUpdates };
      Object.keys(newStyle).forEach(key => {
          // @ts-ignore
          if (newStyle[key] === undefined || newStyle[key] === '') delete newStyle[key];
      });

      newSegments[index] = { ...segment, style: newStyle };
      onUpdate({ ...data, segments: newSegments });
  };

  const handleDeleteSegment = (index: number) => {
    if(!confirm("Delete this lyric segment?")) return;
    const newSegments = [...data.segments];
    newSegments.splice(index, 1);
    onUpdate({ ...data, segments: newSegments });
  };

  const handleAddSegment = () => {
    const newSegments = [...data.segments];
    const lastSeg = newSegments[newSegments.length - 1];
    const newStart = lastSeg ? lastSeg.end + 0.2 : 0;
    const newSegment: Segment = {
        id: Date.now().toString(),
        start: newStart,
        end: newStart + 2.0,
        text: "New Line",
        section: undefined, 
        words: []
    };
    newSegment.words = recalculateWords(newSegment.text, newSegment.start, newSegment.end);
    newSegments.push(newSegment);
    onUpdate({ ...data, segments: newSegments });
  };

  // --- EVENT BLOCK UPDATERS ---

  const handleAddEventBlock = () => {
      const newBlock: EventBlock = {
          id: `evt-${Date.now()}`,
          start: currentTime,
          end: currentTime + 5,
          label: "FX Block",
          overrides: {},
          collapsed: false,
          smoothIn: false,
          smoothOut: false
      };
      onUpdateEventBlocks([...eventBlocks, newBlock].sort((a, b) => a.start - b.start));
  };

  const updateEventBlock = (id: string, updates: Partial<EventBlock>) => {
      let newBlocks = eventBlocks.map(b => b.id === id ? { ...b, ...updates } : b);
      if (updates.start !== undefined) newBlocks.sort((a, b) => a.start - b.start);
      onUpdateEventBlocks(newBlocks);
  };

  const toggleOverride = (blockId: string, key: keyof EffectOverrides) => {
      const block = eventBlocks.find(b => b.id === blockId);
      if(!block) return;

      const current = block.overrides[key];
      // Cycle: undefined (Global) -> true (On) -> false (Off) -> undefined
      let next: boolean | undefined;
      if (current === undefined) next = true;
      else if (current === true) next = false;
      else next = undefined;

      const newOverrides = { ...block.overrides, [key]: next };
      // Remove key if undefined to clean up
      if (next === undefined) delete newOverrides[key];

      updateEventBlock(blockId, { overrides: newOverrides });
  };

  const toggleCustomOverride = (blockId: string, effectId: string) => {
      const block = eventBlocks.find(b => b.id === blockId);
      if(!block) return;

      const currentMap = block.overrides.custom_fx || {};
      const current = currentMap[effectId];

      let next: boolean | undefined;
      if (current === undefined) next = true;
      else if (current === true) next = false;
      else next = undefined;

      const newMap = { ...currentMap, [effectId]: next };
      if (next === undefined) delete newMap[effectId];

      const newOverrides = { ...block.overrides };
      if (Object.keys(newMap).length === 0) {
          delete newOverrides.custom_fx;
      } else {
          // @ts-ignore 
          newOverrides.custom_fx = newMap;
      }

      updateEventBlock(blockId, { overrides: newOverrides });
  };

  const deleteEventBlock = (id: string) => {
      if(!confirm("Delete this event block?")) return;
      onUpdateEventBlocks(eventBlocks.filter(b => b.id !== id));
  };

  // --- RENDER HELPERS ---

  // Combine and sort lyrics and events for display
  const combinedItems = [
      ...data.segments.map((s, i) => ({ type: 'segment' as const, data: s, index: i, start: s.start })),
      ...eventBlocks.map((b, i) => ({ type: 'block' as const, data: b, index: i, start: b.start }))
  ].sort((a, b) => a.start - b.start);

  const SECTION_COLORS: Record<string, string> = {
      verse: 'border-blue-500',
      chorus: 'border-pink-500',
      bridge: 'border-yellow-500',
      intro: 'border-gray-500',
      outro: 'border-red-500'
  };

  const SECTION_BG: Record<string, string> = {
      verse: 'bg-blue-950/40 text-blue-200',
      chorus: 'bg-pink-950/40 text-pink-200',
      bridge: 'bg-yellow-950/40 text-yellow-200',
      intro: 'bg-gray-800/60 text-gray-300',
      outro: 'bg-red-950/40 text-red-200'
  };

  const getSectionColor = (name: string) => SECTION_COLORS[name.toLowerCase().split(' ')[0]] || 'border-gray-600';
  const getSectionBg = (name: string) => SECTION_BG[name.toLowerCase().split(' ')[0]] || 'bg-neutral-800 text-gray-400';

  let currentSection = 'verse'; 
  let isFirstSegment = true; // Track first segment to prevent deleting its section if minimal

  // Auto-scroll logic
  useEffect(() => {
    if (!autoScroll) return;

    const activeItem = combinedItems.find(item => {
        if(item.type === 'segment') return currentTime >= item.data.start && currentTime <= item.data.end;
        if(item.type === 'block') return currentTime >= item.data.start && currentTime <= item.data.end;
        return false;
    });

    if (activeItem && scrollRef.current) {
        const id = activeItem.type === 'segment' ? activeItem.data.id : activeItem.data.id;
        const row = scrollRef.current.querySelector(`[data-id="${id}"]`) as HTMLElement;
        if (row) {
            const container = scrollRef.current;
            const rowTop = row.offsetTop;
            const rowBottom = rowTop + row.offsetHeight;
            const containerTop = container.scrollTop;
            const containerBottom = containerTop + container.offsetHeight;
            if (rowTop < containerTop || rowBottom > containerBottom) {
                 row.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
  }, [currentTime]);

  return (
    <div className="flex flex-col h-full bg-neutral-900 border-l border-white/5">

        {/* VISUAL TRACK */}
        <VisualTimelineTrack 
            duration={duration} 
            items={combinedItems} 
            currentTime={currentTime} 
            onSeek={onSeek} 
        />

        {/* HEADER TOOLBAR */}
        <div className="p-3 border-b border-white/5 flex justify-between items-center bg-neutral-800 shrink-0">
            <div className="flex items-center gap-2">
                <Clock size={16} className="text-cyan-400" /> 
                <span className="text-xs font-bold text-gray-200 uppercase tracking-widest">Detail View</span>
                <button 
                    onClick={() => setAutoScroll(!autoScroll)}
                    className={`ml-2 p-1 rounded-full transition-colors ${autoScroll ? 'bg-cyan-500/20 text-cyan-400' : 'bg-transparent text-gray-600 hover:text-gray-400'}`}
                    title={autoScroll ? "Disable Auto-Scroll" : "Enable Auto-Scroll"}
                >
                    <ArrowDownCircle size={14} />
                </button>
            </div>

            <div className="flex gap-2">
                <button 
                    onClick={handleAddEventBlock}
                    className="text-[10px] flex items-center gap-1 bg-purple-900/50 hover:bg-purple-800/80 border border-purple-500/50 px-3 py-1.5 rounded text-purple-200 transition-colors font-bold"
                >
                    <Zap size={12} /> Event
                </button>
                <button 
                    onClick={handleAddSegment}
                    className="text-[10px] flex items-center gap-1 bg-cyan-900/50 hover:bg-cyan-800/80 border border-cyan-500/50 px-3 py-1.5 rounded text-cyan-200 transition-colors font-bold"
                >
                    <Plus size={12} /> Line
                </button>
            </div>
        </div>

        {/* LIST AREA */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-3" ref={scrollRef}>
            {combinedItems.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-40 text-gray-500 border-2 border-dashed border-white/5 rounded-xl">
                    <AlertCircle className="mb-2 opacity-50" />
                    <span className="text-xs">Timeline Empty</span>
                    <span className="text-xs text-gray-600 mt-1">Add a Lyric Line or FX Event</span>
                </div>
            ) : (
                combinedItems.map((item) => {
                    // --- RENDER LYRIC SEGMENT ---
                    if (item.type === 'segment') {
                        const seg = item.data;
                        const idx = item.index;
                        const isActive = currentTime >= seg.start && currentTime <= seg.end;
                        const currentTab = activeTabMap[seg.id] || 'text';

                        // Handle Section Headers
                        const isNewSection = !!seg.section;
                        // Use the section property if it exists, otherwise use the running currentSection.
                        // However, we want to visually group them. 
                        // If it IS a new section, we update our running 'currentSection' variable.
                        if (isNewSection) currentSection = seg.section!;
                        else if (isFirstSegment && !seg.section) currentSection = 'verse'; // Default first

                        const isFirst = isFirstSegment;
                        isFirstSegment = false; // Next ones are not first

                        return (
                             <div key={seg.id} className="flex flex-col gap-1">
                                {isNewSection && (
                                    <div className={`flex items-center justify-between px-3 py-1.5 rounded-md mt-2 ${getSectionBg(currentSection)} border border-white/5 shadow-sm sticky top-0 z-10 group/section transition-colors`}>
                                        <div className="flex items-center gap-2 flex-1">
                                            <Tag size={12} className="opacity-70" />
                                            {/* EDITABLE SECTION DROPDOWN */}
                                            <select 
                                                value={currentSection}
                                                onChange={(e) => updateSegmentData(idx, { section: e.target.value })}
                                                className="bg-transparent text-[10px] font-bold uppercase tracking-widest outline-none cursor-pointer appearance-none hover:text-white transition-colors w-full"
                                            >
                                                <option value="verse" className="bg-neutral-900 text-blue-400">Verse</option>
                                                <option value="chorus" className="bg-neutral-900 text-pink-400">Chorus</option>
                                                <option value="bridge" className="bg-neutral-900 text-yellow-400">Bridge</option>
                                                <option value="intro" className="bg-neutral-900 text-gray-400">Intro</option>
                                                <option value="outro" className="bg-neutral-900 text-red-400">Outro</option>
                                            </select>
                                        </div>
                                        {/* REMOVE SECTION BUTTON (Merge with previous) - Disable if first item */}
                                        {!isFirst && (
                                            <button 
                                                onClick={() => updateSegmentData(idx, { section: undefined })}
                                                className="text-white/50 hover:text-white p-1 rounded hover:bg-black/20 opacity-0 group-hover/section:opacity-100 transition-opacity"
                                                title="Merge with previous section"
                                            >
                                                <X size={12} />
                                            </button>
                                        )}
                                    </div>
                                )}
                                <div 
                                    data-id={seg.id}
                                    className={`group relative flex flex-col rounded-lg border border-white/5 transition-all duration-200 overflow-hidden ${
                                        isActive ? 'bg-cyan-950/20 border-cyan-500/30' : 'bg-neutral-800/80 hover:border-white/20'
                                    }`}
                                >
                                    {/* Vertical Color Indicator */}
                                    <div className={`absolute left-0 top-0 bottom-0 w-1 ${getSectionColor(currentSection).replace('border-','bg-')}`}></div>

                                    {/* Card Toolbar */}
                                    <div className="flex items-center justify-between p-2 pl-3 bg-black/20 border-b border-white/5">
                                        {/* Tabs */}
                                        <div className="flex gap-1 bg-black/40 p-0.5 rounded-md">
                                            <button 
                                                onClick={() => setTab(seg.id, 'text')}
                                                className={`p-1 rounded text-[10px] flex items-center gap-1 ${currentTab === 'text' ? 'bg-neutral-700 text-white shadow-sm' : 'text-gray-500 hover:text-gray-300'}`}
                                            >
                                                <Type size={12} /> Text
                                            </button>
                                            <button 
                                                onClick={() => setTab(seg.id, 'style')}
                                                className={`p-1 rounded text-[10px] flex items-center gap-1 ${currentTab === 'style' ? 'bg-neutral-700 text-white shadow-sm' : 'text-gray-500 hover:text-gray-300'}`}
                                            >
                                                <Palette size={12} /> Style
                                            </button>
                                        </div>

                                        {/* Actions */}
                                        <div className="flex items-center gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                                             {!isNewSection && (
                                                <button onClick={() => updateSegmentData(idx, { section: 'verse' })} className="p-1 rounded-md hover:bg-white/10 text-gray-400 hover:text-white" title="Start New Section Here">
                                                    <FolderInput size={14} />
                                                </button>
                                             )}
                                             <button onClick={() => onSeek(seg.start)} className={`p-1 rounded-md transition-colors ${isActive ? 'text-cyan-400' : 'hover:bg-white/10 text-gray-400'}`}>
                                                 <PlayCircle size={14} fill={isActive ? "currentColor" : "none"} />
                                             </button>
                                             <button onClick={() => handleDeleteSegment(idx)} className="p-1 rounded-md hover:bg-red-500/20 text-gray-500 hover:text-red-400">
                                                 <Trash2 size={14} />
                                             </button>
                                        </div>
                                    </div>

                                    {/* TAB CONTENT: TEXT */}
                                    {currentTab === 'text' && (
                                        <div className="p-3">
                                            <div className="flex items-center justify-between gap-3 mb-2">
                                                <div className="flex items-center gap-1">
                                                    <TimeInput className="bg-neutral-900 border border-white/10 rounded px-1 w-14 text-[10px] font-mono text-gray-300 outline-none focus:border-cyan-500" value={seg.start} onChange={(val) => updateSegmentData(idx, { start: val })} />
                                                    <span className="text-gray-600 text-[10px]">to</span>
                                                    <TimeInput className="bg-neutral-900 border border-white/10 rounded px-1 w-14 text-[10px] font-mono text-gray-300 outline-none focus:border-cyan-500" value={seg.end} onChange={(val) => updateSegmentData(idx, { end: val })} />
                                                </div>
                                            </div>
                                            <DebouncedTextArea
                                                className={`w-full bg-transparent text-sm outline-none resize-none font-medium leading-relaxed transition-colors placeholder-gray-700 ${isActive ? 'text-white' : 'text-gray-300'}`}
                                                rows={Math.max(1, seg.text.split('\n').length)}
                                                value={seg.text}
                                                onChange={(val) => updateSegmentData(idx, { text: val }, true)} 
                                                onBlur={() => {}} 
                                                placeholder="Enter lyrics..."
                                            />
                                        </div>
                                    )}

                                    {/* TAB CONTENT: STYLE */}
                                    {currentTab === 'style' && (
                                        <div className="p-3 bg-neutral-900/50">
                                            <div className="grid grid-cols-2 gap-3 mb-3">
                                                <div className="space-y-1">
                                                    <label className="text-[9px] text-gray-500 uppercase font-bold">Text Color</label>
                                                    <div className="flex gap-2 items-center">
                                                        <input 
                                                            type="color" 
                                                            value={seg.style?.colorText || projectConfig?.colors.text || '#ffffff'} 
                                                            onChange={(e) => updateSegmentStyle(idx, { colorText: e.target.value })}
                                                            className="w-6 h-6 bg-transparent cursor-pointer rounded overflow-hidden"
                                                        />
                                                        {projectConfig && (
                                                            <div className="flex gap-1">
                                                                {[projectConfig.colors.text, projectConfig.colors.active, projectConfig.colors.secondary].map(c => (
